MIT_DATA = {'set_a': [{'id': 'q004', 'question': 'Which of the following options are related to the reliability of AWS?', 'options': {'A': 'Applying the principle of least privilege to all AWS resources', 'B': 'Automatically provisioning new resources to meet demand', 'C': 'All AWS services are considered Global Services, and this design helps customers serve their international users', 'D': 'Providing compensation to customers if issues occur', 'E': 'Ability to recover quickly from failures'}, 'answer': ['B', 'E'], 'explanation': 'Automatically provisioning new resources to meet demand and the ability to recover quickly from failures are both core reliability principles, ensuring the system continues operating correctly under varying conditions and after failure events.\nApplying the principle of least privilege is a security practice related to access control, not a reliability principle. All AWS services being considered global services is false, as many services are regional, and global reach is a separate concept from reliability. Providing compensation to customers if issues occur describes an SLA remediation mechanism and is not a design principle that contributes to system reliability.', 'isMultiAnswer': True, 'taskStatement': '1.2', 'lastVerified': '2026-06-15', 'services': [], 'domain_id': 1}, {'id': 'q014', 'question': 'What are the benefits of having infrastructure hosted in AWS?', 'options': {'A': 'Increasing speed and agility', 'B': 'Gaining unlimited free storage for all data', 'C': 'Gaining complete control over the physical infrastructure', 'D': 'Operating applications on behalf of customers', 'E': 'All of the physical security and most of the data and network security are taken care of for you'}, 'answer': ['A', 'E'], 'explanation': "AWS increases speed and agility by allowing customers to provision resources in minutes rather than weeks, and handles physical security along with most data and network security so customers can focus on building applications rather than managing infrastructure.\nUnlimited free storage is not an AWS benefit, as storage services such as Amazon S3 and EBS are billed based on the amount of data stored and retrieved. Complete control over physical infrastructure is not available to AWS customers, as AWS owns and manages all physical hardware, data centers, and networking equipment on the customer's behalf. Operating applications on behalf of customers is not an AWS benefit, as customers remain responsible for building, deploying, and managing their own applications under the shared responsibility model.", 'isMultiAnswer': True, 'taskStatement': '1.1', 'lastVerified': '2026-06-15', 'services': [], 'domain_id': 1}, {'id': 'q146', 'question': "A customer is deploying a new application and needs to choose an AWS Region. Which of the following factors could influence the customer's decision?", 'options': {'A': 'Reduced latency to users', 'B': "The application's presentation in the local language", 'C': 'Data sovereignty compliance', 'D': 'Cooling costs in hotter climates', 'E': "Proximity to the customer's office for on-site visits"}, 'answer': ['A', 'C'], 'explanation': "Proximity to end users reduces network latency for a better application experience, and data sovereignty compliance requirements mandate that data remains within certain geographic boundaries, making both primary factors in Region selection.\nPresenting an application in the local language is an application-layer localisation decision handled through software configuration, not a factor that influences which AWS Region infrastructure is deployed in. Cooling costs in hotter climates are an operational expense absorbed entirely by AWS as part of managing its own data centers, and are not a cost or consideration that customers factor into Region selection. Proximity to the customer's office for on-site visits is not a valid technical or regulatory criterion for Region selection, as AWS data centers are not customer-accessible facilities.", 'isMultiAnswer': True, 'domain_id': 1}, {'id': 'q153', 'question': 'What can assist in evaluating an application for migration to the cloud?', 'options': {'A': 'AWS Trusted Advisor', 'B': 'AWS Professional Services', 'C': 'AWS Systems Manager', 'D': 'AWS Partner Network (APN)', 'E': 'AWS Secrets Manager'}, 'answer': ['B', 'D'], 'explanation': 'AWS Professional Services provides expert consulting engagements to help evaluate and plan migrations, and AWS Partner Network partners offer specialized migration expertise through certified consulting and technology firms.\nAWS Trusted Advisor scans existing AWS environments for best practice recommendations across cost, performance, security, and fault tolerance, but does not evaluate whether an application is suitable for migration to the cloud. AWS Systems Manager is an operational management service for configuring, patching, and managing AWS resources at scale, and is not a migration advisory or evaluation service. AWS Secrets Manager is a service for storing and rotating application secrets such as database credentials and API keys, and has no role in evaluating applications for cloud migration.', 'isMultiAnswer': True, 'domain_id': 1}, {'id': 'q010', 'question': 'A Japanese company hosts their applications on Amazon EC2 instances in the Tokyo Region. The company has opened new branches in the United States, and the US users are complaining of high latency. What can the company do to reduce latency for the users in the US while minimizing costs?', 'options': {'A': 'Applying the Route 53 latency-based routing policy', 'B': 'Registering a new US domain name to serve the users in the US', 'C': 'Building a new data center in the US and implementing a hybrid model', 'D': 'Deploying new Amazon EC2 instances in a Region located in the US'}, 'answer': 'D', 'explanation': 'Deploying EC2 instances in a US Region places compute resources physically closer to US users, directly reducing network latency at minimal additional cost.\nApplying a Route 53 latency-based routing policy directs users to the Region with the lowest latency, but this only optimizes routing and does not itself reduce latency if all compute resources remain in Tokyo. Registering a new US domain name changes how users reach the application by name but does not move any compute resources closer to US users or reduce network latency. Building a new data center in the US and implementing a hybrid model introduces significant capital expenditure and operational complexity, contradicting the requirement to minimize costs.', 'isMultiAnswer': False, 'taskStatement': '1.1', 'lastVerified': '2026-06-15', 'services': ['Amazon EC2', 'Amazon Route 53'], 'domain_id': 1}, {'id': 'q013', 'question': 'Adjusting compute capacity dynamically to reduce cost is an implementation of which AWS cloud best practice?', 'options': {'A': 'Build security in every layer', 'B': 'Parallelize tasks', 'C': 'Implement elasticity', 'D': 'Adopt monolithic architecture'}, 'answer': 'C', 'explanation': 'Elasticity is the cloud best practice of dynamically adjusting compute capacity up or down in response to demand, avoiding over-provisioning during low-traffic periods and under-provisioning during peaks, which directly reduces cost.\nBuild security in every layer is the Defense in Depth principle from the Security pillar of the Well-Architected Framework, which addresses threat protection rather than capacity management. Parallelizing tasks is a performance design principle that distributes workloads across multiple smaller components to increase throughput, not a mechanism for dynamically adjusting capacity to control costs. Adopting monolithic architecture consolidates all application components into a single tightly coupled unit, which is the opposite of a cloud best practice and does not support dynamic scaling.', 'isMultiAnswer': False, 'services': [], 'domain_id': 1}, {'id': 'q015', 'question': 'What is the advantage of the AWS-recommended practice of "decoupling" applications?', 'options': {'A': 'Allows treating an application as a single, cohesive unit', 'B': 'Reduces inter-dependencies so that failures do not impact other components of the application', 'C': 'Allows updates of any monolithic application quickly and easily', 'D': 'Allows tracking of any API call made to any AWS service'}, 'answer': 'B', 'explanation': 'Decoupling means designing components to operate independently so that a failure in one part does not cascade into failures across the rest of the application, improving overall resilience.\nTreating an application as a single cohesive unit describes a monolithic architecture, which is the opposite of decoupling and creates tightly coupled dependencies between components. Allowing quick updates to a monolithic application describes an advantage of a well-structured monolith, not of decoupling, and updating a monolith typically requires deploying the entire application as a unit. Tracking API calls made to AWS services describes the function of AWS CloudTrail, which is an auditing and logging service unrelated to application architecture design.', 'isMultiAnswer': False, 'services': [], 'domain_id': 1}, {'id': 'q019', 'question': "One of the most important AWS best-practices to follow is the cloud architecture principle of elasticity. How does this principle improve your architecture's design?", 'options': {'A': 'By automatically scaling your on-premises resources based on changes in demand', 'B': 'By automatically scaling your AWS resources using an Elastic Load Balancer', 'C': 'By reducing interdependencies between application components wherever possible', 'D': 'By automatically provisioning the required AWS resources based on changes in demand'}, 'answer': 'D', 'explanation': 'Elasticity in AWS means the platform automatically provisions and de-provisions resources in response to real-time changes in demand, so workloads consume only what they need and scale back when demand drops.\nAutomatically scaling on-premises resources is not what elasticity describes in the AWS context; elasticity is a cloud characteristic that removes the need to invest in on-premises hardware at all, as the cloud provider dynamically adjusts compute capacity. An Elastic Load Balancer distributes incoming traffic across existing instances to prevent any single instance from being overwhelmed, but it does not add or remove instances in response to demand; that capacity adjustment is performed by Auto Scaling. Reducing interdependencies between application components describes the design principle of loose coupling, which improves resilience and maintainability, but is a separate architectural concept from elasticity.', 'isMultiAnswer': False, 'domain_id': 1}, {'id': 'q023', 'question': 'Which of the following does NOT belong to the AWS Cloud Computing models?', 'options': {'A': 'Platform as a Service (PaaS)', 'B': 'Infrastructure as a Service (IaaS)', 'C': 'Software as a Service (SaaS)', 'D': 'Networking as a Service (NaaS)'}, 'answer': 'D', 'explanation': 'The three recognized AWS cloud computing service models are IaaS, PaaS, and SaaS. Networking as a Service is not one of them and does not exist as a defined cloud computing model in the AWS framework.\nPlatform as a Service is one of the three recognized cloud computing models, providing customers with a managed platform for developing and deploying applications without managing the underlying infrastructure. Infrastructure as a Service is one of the three recognized cloud computing models, giving customers virtualized compute, storage, and networking resources they manage themselves. Software as a Service is one of the three recognized cloud computing models, delivering fully managed applications to end users over the internet without any infrastructure or platform management required.', 'isMultiAnswer': False, 'services': [], 'domain_id': 1}, {'id': 'q065', 'question': 'According to best practices, how should an application be designed to run in the AWS Cloud?', 'options': {'A': 'Use tightly coupled components', 'B': 'Use loosely coupled components', 'C': 'Use monolithic components', 'D': 'Use stateful components'}, 'answer': 'B', 'explanation': 'Using loosely coupled components means each part of an application can scale, fail, and be updated independently without cascading failures to other components, which is the foundational AWS best practice for building resilient and scalable architectures.\nUsing tightly coupled components creates direct dependencies between parts of an application so that a failure or change in one component directly affects others, increasing the risk of cascading failures and making the system harder to scale and maintain independently. A monolithic design combines all components into a single unit that is difficult to scale or update independently, which is the opposite of the modular approach AWS recommends. Stateful components store session data locally on a specific instance, which prevents requests from being distributed freely across instances and undermines horizontal scaling and resilience.', 'isMultiAnswer': False, 'domain_id': 1}, {'id': 'q077', 'question': 'How does AWS shorten the time to provision IT resources?', 'options': {'A': 'It supplies an online IT ticketing platform for resource requests', 'B': 'It supports automatic code validation services', 'C': 'It provides the ability to programmatically provision existing resources', 'D': "It automates the resource request process from a company's IT vendor list"}, 'answer': 'C', 'explanation': "AWS allows resources to be provisioned programmatically through APIs, CloudFormation templates, and SDKs, drastically reducing the time to deploy infrastructure compared to traditional procurement and physical setup.\nAWS does not operate an IT ticketing platform for resource requests. Resources are provisioned on demand through self-service APIs and consoles without requiring formal request and approval workflows. AWS does not shorten provisioning time through code validation services, which are a software quality tool unrelated to how quickly infrastructure can be deployed. AWS does not automate requests from a company's existing IT vendor list, as it replaces traditional vendor procurement entirely by providing infrastructure directly through its own platform.", 'isMultiAnswer': False, 'domain_id': 1}, {'id': 'q084', 'question': 'Web servers running on Amazon EC2 access a legacy application running in a corporate data center. What term would describe this model?', 'options': {'A': 'Cloud-native', 'B': 'Partner network', 'C': 'Hybrid architecture', 'D': 'Infrastructure as a service'}, 'answer': 'C', 'explanation': 'When applications in the AWS Cloud communicate with a legacy application in a corporate data center, this is a hybrid architecture that combines on-premises and cloud resources in a single solution.\nCloud-native describes applications designed and built entirely to run in the cloud, with no dependency on on-premises infrastructure or legacy systems. Partner network refers to the AWS Partner Network, which is a program for technology and consulting companies that build solutions on AWS, and is not a deployment model. Infrastructure as a Service is a cloud service model that provides virtualized compute, storage, and networking resources, and does not describe the combination of cloud and on-premises components in a single architecture.', 'isMultiAnswer': False, 'domain_id': 1}, {'id': 'q099', 'question': 'Distributing workloads across multiple Availability Zones supports which cloud architecture design principle?', 'options': {'A': 'Implement automation', 'B': 'Design for agility', 'C': 'Design for failure', 'D': 'Implement elasticity'}, 'answer': 'C', 'explanation': 'Distributing workloads across multiple Availability Zones ensures the application can continue operating if one AZ fails, embodying the design for failure principle, where the architecture anticipates and accommodates component failures.\nImplement automation refers to reducing manual intervention through scripts and managed services, not to fault tolerance across zones. Design for agility refers to the ability to rapidly experiment and deploy, not to handling infrastructure failures. Implement elasticity refers to automatically scaling resources in response to demand, not to distributing workloads for fault tolerance.', 'isMultiAnswer': False, 'domain_id': 1}, {'id': 'q128', 'question': 'What is an advantage of deploying an application across multiple Availability Zones?', 'options': {'A': 'There is a lower risk of service failure if a natural disaster causes a service disruption in a given AWS Region', 'B': 'The application will have higher availability because it can withstand a service disruption in one Availability Zone', 'C': 'There will be better coverage as Availability Zones are geographically distant and can serve a wider area', 'D': 'There will be decreased application latency that will improve the user experience'}, 'answer': 'B', 'explanation': 'Deploying across multiple Availability Zones keeps an application running when one AZ experiences an outage, as traffic fails over to instances in the remaining AZs, directly increasing availability.\nMultiple AZs within a single Region do not protect against a natural disaster affecting the entire Region, as all AZs in a Region share the same geographic area and would be exposed to the same regional disruption. Availability Zones within a Region are intentionally close together with low-latency links between them, so they do not provide wider geographic coverage or serve users in distant locations. Deploying across multiple AZs redistributes existing resources rather than reducing the distance between the application and its users, so it does not decrease latency.', 'isMultiAnswer': False, 'domain_id': 1}, {'id': 'q130', 'question': 'Which of the following is an AWS Cloud architecture design principle?', 'options': {'A': 'Implement single points of failure', 'B': 'Implement loose coupling', 'C': 'Implement monolithic design', 'D': 'Implement vertical scaling'}, 'answer': 'B', 'explanation': 'Loose coupling is a core AWS cloud architecture principle where components interact through well-defined interfaces, allowing each to scale, update, or fail independently without cascading effects on other parts of the system.\nImplementing single points of failure is an anti-pattern that directly contradicts cloud architecture best practices, as the goal is to eliminate dependencies that could bring down an entire system. Monolithic design tightly couples all application components into a single unit, making it harder to scale, update, or recover individual parts independently. Vertical scaling increases the capacity of a single instance rather than distributing workloads, which limits scalability and creates potential single points of failure.', 'isMultiAnswer': False, 'domain_id': 1}, {'id': 'q132', 'question': 'A company will be moving from an on-premises data center to the AWS Cloud. What would be one financial difference after the move?', 'options': {'A': 'Moving from variable operational expense (opex) to upfront capital expense (capex)', 'B': 'Moving from upfront capital expense (capex) to variable capital expense (capex)', 'C': 'Moving from upfront capital expense (capex) to variable operational expense (opex)', 'D': 'Elimination of upfront capital expense (capex) and elimination of variable operational expense (opex)'}, 'answer': 'C', 'explanation': 'On-premises infrastructure requires large upfront capital expenditures for hardware and facilities, while AWS converts that spending to variable operational expense where you pay only for what you consume with no hardware purchases required.\nMoving from variable operational expense (opex) to upfront capital expense (capex) this reverses the actual direction of the shift, and on-premises environments are characterized by capex, not opex, as the starting point. Moving from upfront capital expense (capex) to variable capital expense (capex) AWS usage is billed as operational expense, not capital expense, so the destination category in this option is incorrect. Elimination of upfront capital expense (capex) and elimination of variable operational expense (opex) moving to AWS eliminates capex but introduces opex rather than eliminating it, as ongoing usage costs are paid as operational expense.', 'isMultiAnswer': False, 'domain_id': 1}, {'id': 'q026', 'question': 'Hundreds of thousands of DDoS attacks are recorded every month worldwide. What service does AWS provide to help protect AWS Customers from these attacks?', 'options': {'A': 'AWS Shield', 'B': 'AWS Config', 'C': 'Amazon Cognito', 'D': 'AWS WAF', 'E': 'AWS KMS'}, 'answer': ['A', 'D'], 'explanation': 'AWS Shield provides managed DDoS protection at the network and transport layers, and AWS WAF lets you create rules that filter malicious web traffic at the application layer. Together they defend against the full spectrum of DDoS attacks.\nAWS Config continuously monitors and records AWS resource configurations to evaluate compliance, and is a configuration management and auditing service with no capability to block or mitigate DDoS traffic. Amazon Cognito is a user identity and authentication service for web and mobile applications, providing sign-up and sign-in functionality and federated identity, and has no DDoS mitigation capabilities. AWS KMS is a key management service for creating and controlling encryption keys used to protect data, and is not involved in network traffic filtering or DDoS defense.', 'isMultiAnswer': True, 'domain_id': 2}, {'id': 'q032', 'question': 'Which of the following are examples of AWS-managed services, where AWS is responsible for the operational and maintenance burdens of running the service?', 'options': {'A': 'Amazon VPC', 'B': 'Amazon DynamoDB', 'C': 'Amazon EMR', 'D': 'AWS IAM', 'E': 'Amazon Elastic Compute Cloud'}, 'answer': ['B', 'C'], 'explanation': 'Amazon DynamoDB and Amazon EMR are fully managed services where AWS handles provisioning, patching, scaling, and maintenance automatically, freeing customers from managing the underlying infrastructure.\nAmazon VPC is a networking construct that customers configure and manage themselves, including subnets, route tables, internet gateways, and security groups, making it a customer-configured resource rather than a fully managed service. AWS IAM is a service customers use to manage their own users, roles, and permissions, and while AWS maintains the IAM infrastructure, customers are responsible for all identity and access configuration. Amazon Elastic Compute Cloud provides virtual servers where customers are responsible for the operating system, installed software, patches, and configuration, making it an infrastructure service where the customer manages the virtual machine layer rather than a fully managed one.', 'isMultiAnswer': True, 'domain_id': 2}, {'id': 'q038', 'question': 'Which of the following are examples of AWS shared controls?', 'options': {'A': 'Patch Management', 'B': 'IAM Management', 'C': 'VPC Management', 'D': 'Configuration Management', 'E': 'Data Center operations'}, 'answer': ['A', 'D'], 'explanation': "Patch Management and Configuration Management are both shared controls where AWS and the customer each manage their own layer independently, with AWS responsible for the infrastructure and customers responsible for their own operating systems and applications.\nIAM Management is a customer responsibility, as customers exclusively control their own users, roles, and permissions within their AWS account. VPC Management is a customer responsibility, as customers define and configure their own virtual network settings including subnets, route tables, and security groups. Data Center operations are exclusively AWS's responsibility, covering all physical infrastructure management.", 'isMultiAnswer': True, 'domain_id': 2}, {'id': 'q048', 'question': 'In the AWS Shared responsibility Model, which of the following are the responsibility of the customer?', 'options': {'A': 'Disk disposal', 'B': 'Controlling physical access to compute resources', 'C': 'Patching the Network infrastructure', 'D': 'Setting password complexity rules', 'E': 'Configuring network access rules'}, 'answer': ['D', 'E'], 'explanation': "Setting password complexity rules and configuring network access rules such as security groups and NACLs are both customer responsibilities, as customers control their own identity policies and network configuration within their AWS environment.\nDisk disposal is AWS's responsibility, as AWS manages the secure decommissioning and destruction of physical storage hardware. Controlling physical access to compute resources is AWS's responsibility, as customers have no access to the underlying physical infrastructure. Patching the network infrastructure is AWS's responsibility, covering the managed networking layer beneath the customer's virtual network.", 'isMultiAnswer': True, 'domain_id': 2}, {'id': 'q003', 'question': 'You have noticed that several critical Amazon EC2 instances have been terminated. Which of the following AWS services would help you determine who took this action?', 'options': {'A': 'Amazon Inspector', 'B': 'AWS CloudTrail', 'C': 'AWS Trusted Advisor', 'D': 'EC2 Instance Usage Report'}, 'answer': 'B', 'explanation': 'AWS CloudTrail records all API calls and account activity across an AWS environment, capturing who performed each action, from which IP address, and at what time, making it the definitive source for identifying who terminated EC2 instances.\nAmazon Inspector is an automated security assessment service that scans EC2 instances and container images for software vulnerabilities and unintended network exposure, and does not record who performed API actions or management events. AWS Trusted Advisor inspects your AWS environment and provides recommendations across security, cost, performance, and fault tolerance, and is an advisory tool rather than an audit log of account activity. EC2 Instance Usage Report provides billing and usage data about EC2 instances and does not contain API call logs or identity information about who terminated instances.', 'isMultiAnswer': False, 'domain_id': 2}, {'id': 'q005', 'question': 'Which statement is true regarding the AWS Shared Responsibility Model?', 'options': {'A': 'Responsibilities vary depending on the services used', 'B': 'Security of the IaaS services is the responsibility of AWS', 'C': 'Patching the guest OS is always the responsibility of AWS', 'D': 'Security of the managed services is the responsibility of the customer'}, 'answer': 'A', 'explanation': "Under the Shared Responsibility Model, who is responsible for what shifts depending on the service type, with AWS taking on more responsibility for managed services while customers handle more of the stack for IaaS services.\nSecurity of IaaS services is not solely AWS's responsibility, as customers using IaaS must manage the guest operating system, application stack, and data, while AWS is only responsible for the underlying infrastructure. Patching the guest OS is not always AWS's responsibility, as for IaaS services such as EC2 the customer is fully responsible for patching the operating system they run on their instances. Security of managed services is not solely the customer's responsibility, as AWS takes on significantly more of the security burden for managed services such as RDS and Lambda, covering the underlying platform and infrastructure layers.", 'isMultiAnswer': False, 'domain_id': 2}, {'id': 'q011', 'question': 'An organization has a large number of technical employees who operate their AWS Cloud infrastructure. What does AWS provide to help organize them into teams and then assign the appropriate permissions for each team?', 'options': {'A': 'IAM roles', 'B': 'IAM users', 'C': 'IAM user groups', 'D': 'AWS Organizations'}, 'answer': 'C', 'explanation': 'IAM user groups let you organize multiple users together and assign shared permissions at the group level via IAM policies, making it easy to manage access for entire teams without configuring each user individually.\nIAM roles provide temporary security credentials that can be assumed by users, services, or applications, and are not designed to organize teams or assign shared permissions to a fixed set of users in the way groups are. IAM users are individual identities each with their own credentials and permissions, and managing large numbers of users individually by attaching policies to each one is impractical compared to using groups. AWS Organizations manages multiple AWS accounts under a single structure for consolidated billing and policy enforcement, and is not the service used to organize individual IAM users into teams within a single account.', 'isMultiAnswer': False, 'domain_id': 2}, {'id': 'q022', 'question': 'What does the "Principle of Least Privilege" refer to?', 'options': {'A': 'You should grant your users only the permissions they need when they need them and nothing more', 'B': 'All IAM users should have at least the necessary permissions to access the core AWS services', 'C': 'All trusted IAM users should have access to any AWS service in the respective AWS account', 'D': 'IAM users should not be granted any permissions; to keep your account safe'}, 'answer': 'A', 'explanation': 'The Principle of Least Privilege means granting users only the exact permissions they need to perform their job and nothing beyond that, minimizing the risk of accidental or malicious misuse of AWS resources.\nGranting IAM users at least the necessary permissions to access core AWS services describes a minimum baseline, which is the opposite of least privilege; least privilege means restricting permissions to only what is needed for a specific task rather than ensuring access to common services. Granting all trusted users access to any AWS service in the account contradicts least privilege by providing broad unrestricted access rather than targeted permissions. Granting no permissions to any IAM user is not a practical interpretation of least privilege, which is about granting the minimum required permissions rather than granting none at all.', 'isMultiAnswer': False, 'domain_id': 2}, {'id': 'q031', 'question': 'Which of the following services allows customers to manage their agreements with AWS?', 'options': {'A': 'AWS Artifact', 'B': 'AWS Certificate Manager', 'C': 'AWS Systems Manager', 'D': 'AWS Organizations'}, 'answer': 'A', 'explanation': 'AWS Artifact is a self-service portal where customers can access and manage AWS compliance reports and agreements, including NDA and Business Associate Addendum (BAA) documents that govern the relationship between customers and AWS.\nAWS Certificate Manager provisions and manages SSL/TLS certificates for use with AWS services, and is a certificate management service rather than an agreement management portal. AWS Systems Manager provides operational tools for managing AWS resources at scale including patching, parameter storage, and session management, and is not used to manage contractual agreements with AWS. AWS Organizations manages multiple AWS accounts under a master account structure for consolidated billing and service control policies, and is not a portal for managing compliance reports or agreements.', 'isMultiAnswer': False, 'domain_id': 2}, {'id': 'q036', 'question': 'Which of the following must an IAM user provide to interact with AWS services using the AWS Command Line Interface (AWS CLI)?', 'options': {'A': 'Access keys', 'B': 'Secret token', 'C': 'UserID', 'D': 'User name and password'}, 'answer': 'A', 'explanation': 'IAM access keys, consisting of an access key ID and secret access key, are the credentials used to authenticate API requests programmatically through the AWS CLI, allowing IAM users to interact with AWS services from the command line without the Management Console.\nA secret token is not a standard IAM credential type for CLI access; temporary security credentials issued to IAM roles include a session token in addition to an access key ID and secret, but a standalone secret token alone is not used for CLI authentication. A UserID is an internal AWS identifier assigned to IAM users but is not a credential that can be supplied to authenticate CLI requests. A user name and password are the credentials used to log in to the AWS Management Console interactively, not to authenticate programmatic CLI requests which require access keys.', 'isMultiAnswer': False, 'domain_id': 2}, {'id': 'q037', 'question': 'You have AWS Basic support, and you have discovered that some AWS resources are being used maliciously, and those resources could potentially compromise your data. What should you do?', 'options': {'A': 'Contact the AWS Customer Service team', 'B': 'Contact the AWS Abuse Team', 'C': 'Contact the AWS Concierge team', 'D': 'Contact the AWS Security team'}, 'answer': 'B', 'explanation': "The AWS Abuse Team handles reports of AWS infrastructure being used for malicious activity such as hacking, spam, or unauthorised use, and this channel is available to all customers regardless of their support tier.\nThe AWS Customer Service team handles general account and billing enquiries, and is not the designated contact for reporting malicious use of AWS infrastructure. The AWS Concierge team is a dedicated support resource available exclusively to Enterprise support plan customers for billing and account assistance, and does not handle abuse or malicious activity reports. The AWS Security team manages AWS's own internal security posture and vulnerability disclosure program, and is not the correct channel for customers to report malicious use of AWS resources within their own accounts.", 'isMultiAnswer': False, 'domain_id': 2}, {'id': 'q043', 'question': 'Under the shared responsibility model, which of the following is the responsibility of AWS?', 'options': {'A': 'Client-side encryption', 'B': 'Configuring infrastructure devices', 'C': 'Server-side encryption', 'D': 'Filtering traffic with Security Groups'}, 'answer': 'B', 'explanation': "Configuring infrastructure devices such as networking hardware and physical servers is entirely AWS's responsibility, as customers have no access to or control over the underlying physical infrastructure.\nClient-side encryption is the customer's responsibility, as customers choose whether and how to encrypt data before sending it to AWS. Server-side encryption is also the customer's responsibility, as customers decide whether to enable encryption at rest for their data stored in AWS services. Filtering traffic with Security Groups is the customer's responsibility, as customers define and manage their own Security Group rules within their AWS environment.", 'isMultiAnswer': False, 'domain_id': 2}, {'id': 'q046', 'question': 'Your company is developing a critical web application in AWS, and the security of the application is a top priority. Which of the following AWS services will provide infrastructure security optimization recommendations?', 'options': {'A': 'AWS Shield', 'B': 'AWS Management Console', 'C': 'AWS Secrets Manager', 'D': 'AWS Trusted Advisor'}, 'answer': 'D', 'explanation': 'AWS Trusted Advisor inspects your AWS environment and provides real-time recommendations across five categories including security, cost optimization, performance, fault tolerance, and service limits, helping you follow AWS best practices.\nAWS Shield is a managed DDoS protection service that defends against distributed denial of service attacks, and does not provide broad infrastructure security recommendations. AWS Management Console is the web-based interface for accessing and managing AWS services, and does not analyze or make recommendations about your environment. AWS Secrets Manager is a service for storing, rotating, and managing access to secrets such as database credentials and API keys, and does not provide infrastructure optimization recommendations.', 'isMultiAnswer': False, 'domain_id': 2}, {'id': 'q056', 'question': "Which of the following is the customer's responsibility under the AWS shared responsibility model?", 'options': {'A': 'Patching underlying infrastructure', 'B': 'Physical security', 'C': 'Patching Amazon EC2 instances', 'D': 'Patching network infrastructure'}, 'answer': 'C', 'explanation': "Customers are responsible for patching the operating system and software on EC2 instances they launch, as the guest OS and everything running on it falls within the customer's side of the Shared Responsibility Model.\nPatching underlying infrastructure is AWS's responsibility, covering the hypervisor and physical hardware beneath the customer's instances. Physical security is AWS's responsibility exclusively, as customers have no access to or control over AWS data centers. Patching network infrastructure is AWS's responsibility, covering the managed networking layer that underpins all customer virtual networks.", 'isMultiAnswer': False, 'domain_id': 2}, {'id': 'q057', 'question': 'According to the AWS shared responsibility model who is responsible for configuration management?', 'options': {'A': 'It is solely the responsibility of the customer', 'B': 'It is solely the responsibility of AWS', 'C': 'It is shared between AWS and the customer', 'D': 'It is not part of the AWS shared responsibility model'}, 'answer': 'C', 'explanation': "Configuration management is a shared control where AWS manages the configuration of its infrastructure, while the customer is responsible for configuring the operating systems, databases, and applications they deploy.\nConfiguration management is not solely the customer's responsibility, as AWS independently manages the configuration of all underlying infrastructure components including hardware, networking, and managed services. Configuration management is not solely AWS's responsibility, as customers retain full accountability for configuring the resources and workloads they deploy on top of the AWS infrastructure. Configuration management is explicitly recognized as a shared control in the AWS Shared Responsibility Model and is therefore fully accounted for within it.", 'isMultiAnswer': False, 'domain_id': 2}, {'id': 'q058', 'question': 'Which security service automatically recognizes and classifies sensitive data or intellectual property on AWS?', 'options': {'A': 'Amazon GuardDuty', 'B': 'Amazon Macie', 'C': 'Amazon Inspector', 'D': 'AWS Shield'}, 'answer': 'B', 'explanation': 'Amazon Macie uses machine learning to automatically discover, classify, and protect sensitive data such as personally identifiable information and intellectual property stored in Amazon S3, making it the correct service for automatically recognizing and classifying sensitive data.\nAmazon GuardDuty is a threat detection service that continuously monitors AWS accounts and workloads for malicious activity and anomalous behavior using machine learning and threat intelligence, and focuses on detecting security threats rather than classifying data. Amazon Inspector is an automated security assessment service that scans EC2 instances and container images for software vulnerabilities and unintended network exposure, and does not classify or discover sensitive data stored in S3. AWS Shield provides managed DDoS protection at the network and transport layers, and is a traffic protection service with no capability to recognize or classify sensitive data.', 'isMultiAnswer': False, 'domain_id': 2}, {'id': 'q064', 'question': 'Which AWS service allows users to identify the changes made to a resource over time?', 'options': {'A': 'Amazon Inspector', 'B': 'AWS Config', 'C': 'AWS Service Catalog', 'D': 'AWS IAM'}, 'answer': 'B', 'explanation': 'AWS Config continuously tracks and records configuration changes to AWS resources over time, allowing you to review historical configurations and identify what changed and when.\nAmazon Inspector is an automated vulnerability assessment service that scans EC2 instances for security findings, not a service for tracking configuration changes over time. AWS Service Catalog allows organizations to create and manage approved portfolios of IT services for deployment, unrelated to tracking resource changes. AWS IAM manages user identities, roles, and access permissions within an AWS account and does not record or track configuration changes to resources.', 'isMultiAnswer': False, 'domain_id': 2}, {'id': 'q075', 'question': 'Access keys in AWS Identity and Access Management (IAM) are used to:', 'options': {'A': 'Log in to the AWS Management Console', 'B': 'Make programmatic calls to AWS from AWS APIs', 'C': 'Log in to Amazon EC2 instances', 'D': 'Authenticate to AWS CodeCommit repositories'}, 'answer': 'B', 'explanation': 'IAM access keys, consisting of an access key ID and a secret access key, are the credentials used to authenticate programmatic calls to AWS APIs via the CLI, SDKs, or direct HTTP requests, allowing applications and scripts to interact with AWS services without using the console.\nLogging in to the AWS Management Console requires a user name and password combination, not access keys, which are reserved for programmatic and CLI access rather than browser-based console authentication. Logging in to Amazon EC2 instances uses SSH key pairs on Linux instances or a password retrieved via the console for Windows instances, and is separate from the IAM access keys used for API authentication. Authenticating to AWS CodeCommit repositories uses Git credentials or SSH keys configured separately from IAM access keys, though access keys can be used with the AWS CLI to interact with CodeCommit programmatically.', 'isMultiAnswer': False, 'domain_id': 2}, {'id': 'q091', 'question': 'The user is fully responsible for which action when running workloads on AWS?', 'options': {'A': 'Patching the infrastructure components', 'B': 'Maintaining the underlying infrastructure components', 'C': 'Maintaining physical and environmental controls', 'D': 'Implementing controls to route application traffic'}, 'answer': 'D', 'explanation': "Customers are fully responsible for implementing application-level controls such as routing traffic within their own systems, as these decisions sit entirely within the customer's layer of the Shared Responsibility Model.\nPatching the infrastructure components is AWS's responsibility, covering the physical servers, networking equipment, and hypervisor layer beneath the customer's workloads. Maintaining the underlying infrastructure components is AWS's responsibility, as customers have no access to or control over the physical hardware running their workloads. Maintaining physical and environmental controls is AWS's responsibility exclusively, covering data center facilities, power, cooling, and physical security.", 'isMultiAnswer': False, 'domain_id': 2}, {'id': 'q018', 'question': 'What should you do in order to keep the data on EBS volumes safe?', 'options': {'A': 'Create EBS snapshots', 'B': 'Ensure that EBS data is encrypted at rest', 'C': 'Replicate EBS volumes across multiple Availability Zones', 'D': 'Use AWS Backup to automate and manage backup schedules', 'E': 'Increase the size of the EBS volume regularly'}, 'answer': ['A', 'B'], 'explanation': 'EBS snapshots create point-in-time backups of your volume stored durably in Amazon S3, allowing data to be restored if a volume is lost or corrupted. Enabling encryption at rest protects the data stored on EBS volumes from unauthorised access using AWS KMS managed keys.\nReplicating EBS volumes across multiple Availability Zones improves availability but does not protect against accidental deletion or data corruption, as a replicated volume would reflect the same corrupted state. Using AWS Backup automates backup management across multiple AWS services but is not itself a direct method of keeping EBS data safe without also taking snapshots. Increasing the size of an EBS volume adds storage capacity but has no effect on data protection or security.', 'isMultiAnswer': True, 'domain_id': 3}, {'id': 'q039', 'question': 'In order to implement best practices when dealing with a “Single Point of Failure,” you should attempt to build as much automation as possible in both detecting and reacting to failure. Which of the following AWS services would help?', 'options': {'A': 'ELB', 'B': 'Auto Scaling', 'C': 'Amazon Athena', 'D': 'ECR', 'E': 'Amazon EC2'}, 'answer': ['A', 'B'], 'explanation': 'Elastic Load Balancing automatically detects unhealthy instances and stops sending traffic to them, while Auto Scaling automatically replaces failed instances, together eliminating single points of failure through automated detection and recovery.\nAmazon Athena is a serverless query service for analyzing data stored in S3 using standard SQL and has no role in detecting or recovering from infrastructure failures. Amazon Elastic Container Registry is a managed container image registry for storing and managing Docker images, unrelated to failure detection or automated recovery. Amazon EC2 provides the virtual server instances themselves but does not natively automate the detection of or response to failures without ELB and Auto Scaling configured around it.', 'isMultiAnswer': True, 'domain_id': 3}, {'id': 'q044', 'question': 'What does the AWS Health Dashboard provide?', 'options': {'A': 'Detailed troubleshooting guidance to address AWS events impacting your resources', 'B': 'Health checks for Auto Scaling instances', 'C': 'Recommendations for Cost Optimization', 'D': 'A dashboard detailing vulnerabilities in your applications', 'E': 'Personalized view of AWS service health'}, 'answer': ['A', 'E'], 'explanation': 'AWS Health Dashboard provides a personalized view of how AWS service events affect your specific resources, and detailed troubleshooting guidance to help you respond to and resolve those events.\nHealth checks for Auto Scaling instances are a feature of Amazon EC2 Auto Scaling that monitors instance health and replaces unhealthy instances automatically, and are not a capability of the AWS Health Dashboard. Recommendations for cost optimization are provided by AWS Trusted Advisor, which inspects your environment and suggests ways to reduce spending, and are not a feature of the AWS Health Dashboard. A dashboard detailing vulnerabilities in applications describes Amazon Inspector, which scans for software vulnerabilities and unintended network exposure, and is not a function of the AWS Health Dashboard.', 'isMultiAnswer': True, 'domain_id': 3}, {'id': 'q047', 'question': 'Which of the following is not a benefit of Amazon S3?', 'options': {'A': 'Amazon S3 provides unlimited storage for any type of data', 'B': 'Amazon S3 can run any type of application or backend system', 'C': 'Amazon S3 stores any number of objects, but with object size limits', 'D': 'Amazon S3 can be scaled manually to store and retrieve any amount of data from anywhere', 'E': "Amazon S3 provides 99.999999999% (11 9's) of data durability"}, 'answer': ['B', 'D'], 'explanation': 'Amazon S3 cannot run applications or backend systems, as it is an object storage service rather than a compute platform. Running applications and backend systems is the function of services such as Amazon EC2 and AWS Lambda. Amazon S3 scales automatically rather than manually, so the claim that it scales manually is factually incorrect and therefore not a genuine benefit.\nAmazon S3 does provide virtually unlimited storage for any type of data as objects, making option A a true statement and therefore not the answer. Amazon S3 stores any number of objects but does impose a 5 TB size limit per individual object, making option C an accurate description of its behavior. Amazon S3 is designed to provide 99.999999999% durability for objects stored across its infrastructure, making option E a genuine and well-known benefit.', 'isMultiAnswer': True, 'domain_id': 3}, {'id': 'q053', 'question': 'Which of the following are features of Amazon CloudWatch Logs?', 'options': {'A': 'Summaries by Amazon Simple Notification Service (Amazon SNS)', 'B': 'Free Amazon OpenSearch Service analytics', 'C': 'Provided at no charge', 'D': 'Real-time monitoring', 'E': 'Adjustable retention'}, 'answer': ['D', 'E'], 'explanation': 'Amazon CloudWatch Logs supports real-time monitoring of log data and configurable retention periods, allowing you to control exactly how long log data is kept before it is automatically deleted.\nAmazon SNS is a notification and messaging service that can be triggered by CloudWatch alarms, but summarizing log data is not a native feature of CloudWatch Logs. Amazon CloudWatch Logs is not free, as charges apply based on the volume of data ingested, stored, and analyzed. Amazon OpenSearch Service is a separate analytics service that can be integrated with CloudWatch Logs as a destination, but free OpenSearch analytics is not a native feature of CloudWatch Logs.', 'isMultiAnswer': True, 'domain_id': 3}, {'id': 'q001', 'question': 'AWS allows users to manage their resources using a web based user interface. What is the name of this interface?', 'options': {'A': 'AWS CLI', 'B': 'AWS API', 'C': 'AWS SDK', 'D': 'AWS Management Console'}, 'answer': 'D', 'explanation': 'The AWS Management Console is the web-based graphical interface used to manage and interact with AWS resources directly from a browser.\nThe AWS CLI is a command-line tool that allows users to interact with AWS services through typed commands in a terminal, not through a web-based graphical interface. The AWS API provides programmatic access to AWS services through HTTP requests made directly by applications or scripts, and has no graphical user interface. The AWS SDK provides libraries and tools for interacting with AWS services through application code in languages such as Python, Java, and JavaScript, and is not a user-facing interface for managing resources.', 'isMultiAnswer': False, 'domain_id': 3}, {'id': 'q002', 'question': 'Which of the following is an example of horizontal scaling in the AWS Cloud?', 'options': {'A': 'Replacing an existing EC2 instance with a larger, more powerful one', 'B': 'Increasing the compute capacity of a single EC2 instance to address the growing demands of an application', 'C': 'Adding more RAM capacity to an EC2 instance', 'D': 'Adding more EC2 instances of the same size to handle an increase in traffic'}, 'answer': 'D', 'explanation': 'Horizontal scaling means adding more instances of the same size to distribute load, while vertical scaling means increasing the capacity of a single instance.\nReplacing an existing instance with a larger one is vertical scaling, not horizontal. Increasing the compute capacity of a single instance describes vertical scaling, which is the opposite of horizontal scaling. Adding more RAM to a single instance is another form of vertical scaling, as it increases the power of one instance rather than adding more instances.', 'isMultiAnswer': False, 'domain_id': 3}, {'id': 'q007', 'question': 'A company has developed an eCommerce web application on AWS. What should they do to ensure that the application has the highest level of availability?', 'options': {'A': 'Deploy the application across multiple Availability Zones and edge locations', 'B': 'Deploy the application across multiple Availability Zones and subnets', 'C': 'Deploy the application across multiple Regions and Availability Zones', 'D': 'Deploy the application across multiple VPCs and subnets'}, 'answer': 'C', 'explanation': 'Deploying across multiple Regions and Availability Zones provides the highest level of availability by protecting against both Availability Zone-level failures and Region-level failures simultaneously.\nDeploying across multiple Availability Zones and edge locations adds content delivery reach through CloudFront but does not protect application infrastructure against a Regional failure. Deploying across multiple Availability Zones and subnets improves resilience against isolated failures within a Region, but a Regional outage would still affect the entire deployment. Deploying across multiple VPCs and subnets creates network segmentation within a Region but provides no geographic redundancy against Availability Zone or Regional failures.', 'isMultiAnswer': False, 'domain_id': 3}, {'id': 'q012', 'question': 'A company has decided to migrate its Oracle database to AWS. Which AWS service can help achieve this without negatively impacting the functionality of the source database?', 'options': {'A': 'AWS OpsWorks', 'B': 'AWS Database Migration Service', 'C': 'AWS Server Migration Service', 'D': 'AWS Application Discovery Service'}, 'answer': 'B', 'explanation': 'AWS Database Migration Service is purpose-built for migrating databases to AWS with minimal downtime, keeping the source database fully operational throughout the migration process.\nAWS OpsWorks (deprecated) is a configuration management service using Chef and Puppet for automating server configuration and has no capability for database migration. AWS Server Migration Service is designed for migrating virtual machines from on-premises environments to AWS, not for migrating databases. AWS Application Discovery Service helps plan migrations by collecting data about on-premises servers and dependencies, but does not perform the actual migration of databases or any other workloads.', 'isMultiAnswer': False, 'domain_id': 3}, {'id': 'q021', 'question': 'What does Amazon CloudFront use to distribute content to global users with low latency?', 'options': {'A': 'AWS Global Accelerator', 'B': 'AWS Regions', 'C': 'AWS Edge Locations', 'D': 'AWS Availability Zones'}, 'answer': 'C', 'explanation': 'CloudFront delivers content from edge locations, a global network of points of presence that cache content close to end users to minimize latency.\nAWS Global Accelerator also uses the AWS global network to improve performance for global users, but it routes traffic to optimal regional endpoints rather than caching content at edge locations, making it a different service with a different mechanism. AWS Regions are geographic areas containing multiple Availability Zones where customers deploy workloads, and CloudFront does not distribute content by routing requests to a Region in the way a standard application deployment would. AWS Availability Zones are isolated data center clusters within a Region used for redundancy and fault tolerance, and are not the mechanism CloudFront uses to cache and serve content to global users.', 'isMultiAnswer': False, 'domain_id': 3}, {'id': 'q025', 'question': 'Which service provides DNS in the AWS cloud?', 'options': {'A': 'Amazon Route 53', 'B': 'AWS Config', 'C': 'Amazon CloudFront', 'D': 'Amazon EMR'}, 'answer': 'A', 'explanation': 'Amazon Route 53 is the scalable and highly available Domain Name System service provided by AWS, used to route end users to applications by translating domain names to IP addresses.\nAWS Config continuously tracks and records the configuration of AWS resources to assess compliance and detect changes, and has no DNS or traffic routing capability. Amazon CloudFront is a content delivery network that caches and distributes content at edge locations worldwide to reduce latency, and while it works alongside Route 53 in many architectures it is a content delivery service rather than a DNS service. Amazon EMR is a managed cluster platform for processing large volumes of data using big data frameworks such as Hadoop and Spark, and has no connection to DNS or network routing.', 'isMultiAnswer': False, 'domain_id': 3}, {'id': 'q027', 'question': "A company is deploying a new two-tier web application in AWS. Where should the most frequently accessed data be stored so that the application's response time is optimal?", 'options': {'A': 'AWS OpsWorks', 'B': 'AWS Storage Gateway', 'C': 'Amazon EBS volume', 'D': 'Amazon ElastiCache'}, 'answer': 'D', 'explanation': 'Amazon ElastiCache is an in-memory caching service that provides sub-millisecond response times for frequently accessed data, making it the purpose-built solution for optimizing application response time in a two-tier web architecture.\nAWS OpsWorks (deprecated) is a configuration management service that automates server setup and maintenance using Chef and Puppet, and has no capability to store data or improve application response times through caching. AWS Storage Gateway connects on-premises environments to AWS cloud storage for hybrid storage integration, and is a storage bridging service rather than a low-latency caching layer for web application data. Amazon EBS provides persistent block storage volumes that attach directly to EC2 instances for low-latency disk access, and while it offers faster access than object storage, it does not provide the sub-millisecond in-memory performance that ElastiCache delivers for frequently accessed data.', 'isMultiAnswer': False, 'domain_id': 3}, {'id': 'q030', 'question': 'Which of the following can be described as a global content delivery network (CDN) service?', 'options': {'A': 'AWS VPN', 'B': 'AWS Direct Connect', 'C': 'AWS Regions', 'D': 'Amazon CloudFront'}, 'answer': 'D', 'explanation': "Amazon CloudFront is AWS's global CDN service that caches and delivers content from edge locations worldwide, reducing latency for end users regardless of their location.\nAWS VPN creates encrypted network connections between on-premises infrastructure and AWS over the public internet, and has no content delivery or caching capability. AWS Direct Connect provides a dedicated private network link between on-premises infrastructure and AWS, and is a connectivity service rather than a content delivery network. AWS Regions are geographic areas containing multiple Availability Zones where AWS infrastructure is hosted, and are a component of global infrastructure rather than a CDN service.", 'isMultiAnswer': False, 'domain_id': 3}, {'id': 'q033', 'question': 'Your company has a data store application that requires access to a NoSQL database. Which AWS database offering would meet this requirement?', 'options': {'A': 'Amazon Aurora', 'B': 'Amazon DynamoDB', 'C': 'Amazon Elastic Block Store', 'D': 'Amazon Redshift'}, 'answer': 'B', 'explanation': 'Amazon DynamoDB is a fully managed NoSQL key-value and document database designed for applications that need fast, flexible, schema-less data storage.\nAmazon Aurora is a fully managed relational database compatible with MySQL and PostgreSQL that uses structured schemas and SQL, and does not support NoSQL data models. Amazon Elastic Block Store provides block storage volumes that attach to EC2 instances for use as persistent disks, and is a storage service with no database capability of any kind. Amazon Redshift is a managed data warehouse service optimized for running analytical SQL queries across large datasets, and is not a NoSQL database.', 'isMultiAnswer': False, 'domain_id': 3}, {'id': 'q041', 'question': 'A developer is planning to build a two-tier web application that has a MySQL database layer. Which of the following AWS database services would provide automated backups for the application?', 'options': {'A': 'A MySQL database installed on an EC2 instance', 'B': 'Amazon Aurora', 'C': 'Amazon DynamoDB', 'D': 'Amazon Neptune'}, 'answer': 'B', 'explanation': 'Amazon Aurora is a MySQL-compatible managed relational database that automatically handles backups, replication, and failover, unlike running MySQL on EC2 where the customer manages everything themselves.\nA MySQL database installed on an EC2 instance is a self-managed deployment where the customer is responsible for configuring and running their own backup processes, with no automated backup capability provided by AWS. Amazon DynamoDB is a fully managed NoSQL key-value and document database that is not MySQL-compatible and is not suited to replacing a relational MySQL database layer. Amazon Neptune is a fully managed graph database service designed for highly connected datasets such as social networks and knowledge graphs, and is not a relational database option for MySQL workloads.', 'isMultiAnswer': False, 'domain_id': 3}, {'id': 'q042', 'question': 'What is the AWS service that enables AWS architects to manage infrastructure as code?', 'options': {'A': 'AWS CloudFormation', 'B': 'AWS Config', 'C': 'Amazon SES', 'D': 'Amazon EMR'}, 'answer': 'A', 'explanation': 'AWS CloudFormation lets you define your entire AWS infrastructure as code using JSON or YAML templates, enabling repeatable and automated provisioning of resources without manual configuration.\nAWS Config continuously monitors and records the configuration state of AWS resources and evaluates them against desired settings, but it does not provision or manage infrastructure. Amazon SES is a cloud-based email sending and receiving service, entirely unrelated to infrastructure management. Amazon EMR is a managed big data processing service for running frameworks such as Apache Spark and Hadoop, unrelated to infrastructure as code.', 'isMultiAnswer': False, 'domain_id': 3}, {'id': 'q045', 'question': "You have deployed your application on multiple Amazon EC2 instances. Your customers complain that sometimes they can't reach your application. Which AWS service allows you to monitor the performance of your EC2 instances to assist in troubleshooting these issues?", 'options': {'A': 'AWS Lambda', 'B': 'AWS Config', 'C': 'Amazon CloudWatch', 'D': 'AWS CloudTrail'}, 'answer': 'C', 'explanation': 'Amazon CloudWatch collects and monitors metrics, logs, and events from EC2 instances, enabling you to set alarms and visualise performance data to diagnose availability and performance issues affecting your application.\nAWS Lambda is a serverless compute service that runs code in response to events and has no capability for monitoring the performance or availability of EC2 instances. AWS Config records and evaluates configuration changes to AWS resources for compliance and auditing purposes, but does not collect performance metrics or help troubleshoot availability issues. AWS CloudTrail records API calls and user activity across your AWS account for auditing and governance purposes, but does not monitor instance performance metrics or application availability.', 'isMultiAnswer': False, 'domain_id': 3}, {'id': 'q054', 'question': 'Which of the following is an AWS-managed compute service?', 'options': {'A': 'Amazon SWF', 'B': 'Amazon EC2', 'C': 'AWS Lambda', 'D': 'Amazon Aurora'}, 'answer': 'C', 'explanation': 'AWS Lambda is a fully managed serverless compute service where you upload your code and AWS handles all underlying infrastructure, patching, and scaling automatically, with no server management required from the customer.\nAmazon Simple Workflow Service is a workflow orchestration service for coordinating tasks across distributed application components, and is not a compute service that provides or manages underlying infrastructure. Amazon EC2 provides virtual servers with full operating system access, but requires the customer to manage the guest operating system, patching, and capacity configuration, making it a customer-managed rather than a fully AWS-managed compute service. Amazon Aurora is a fully managed relational database service compatible with MySQL and PostgreSQL, and is a database service rather than a compute service.', 'isMultiAnswer': False, 'domain_id': 3}, {'id': 'q073', 'question': 'A company wants to focus on business activities instead of managing compute and capacity. Which AWS service can be used to automatically add or remove Amazon EC2 instances based on demand?', 'options': {'A': 'Elastic Load Balancer', 'B': 'Amazon EC2 Auto Scaling', 'C': 'Amazon Route 53', 'D': 'Amazon CloudFront'}, 'answer': 'B', 'explanation': 'Amazon EC2 Auto Scaling monitors demand and automatically adds or removes EC2 instances to maintain performance and minimize cost, freeing teams from manual capacity management so they can focus on their applications.\nElastic Load Balancing distributes incoming traffic across existing EC2 instances to prevent any single instance from being overwhelmed, but does not add or remove instances in response to changes in demand. Amazon Route 53 is a DNS and domain routing service that directs users to application endpoints and has no role in provisioning or removing compute capacity. Amazon CloudFront is a content delivery network that caches and serves content from edge locations closer to end users, and does not manage or scale EC2 instance capacity.', 'isMultiAnswer': False, 'domain_id': 3}, {'id': 'q076', 'question': 'Which AWS service can be used to query stored datasets directly from Amazon S3 using standard SQL?', 'options': {'A': 'AWS Glue', 'B': 'Amazon EMR', 'C': 'Amazon CloudSearch', 'D': 'Amazon Athena'}, 'answer': 'D', 'explanation': 'Amazon Athena lets you run standard SQL queries directly against data stored in S3 without loading it into a database first, making it the purpose-built service for querying datasets directly from S3.\nAWS Glue is a serverless ETL service for discovering, preparing, and transforming data for analytics pipelines, not for running ad hoc SQL queries directly against S3. Amazon EMR provides managed clusters for processing large datasets using frameworks like Spark and Hadoop, but requires provisioning infrastructure rather than querying S3 directly with standard SQL. Amazon CloudSearch is a managed search service for adding full-text search functionality to applications and has no capability for SQL-based data querying.', 'isMultiAnswer': False, 'domain_id': 3}, {'id': 'q085', 'question': 'What technology enables compute capacity to adjust as loads change?', 'options': {'A': 'Load balancing', 'B': 'Automatic failover', 'C': 'Round robin', 'D': 'Auto Scaling'}, 'answer': 'D', 'explanation': 'Auto Scaling monitors load and automatically adjusts the number of compute instances to match demand, ensuring capacity scales up during peak periods and scales back down when demand drops, without any manual intervention.\nLoad balancing distributes incoming traffic across existing compute instances to prevent any single instance from being overwhelmed, but does not add or remove capacity in response to changing load. Automatic failover redirects traffic to a healthy instance or resource when a failure is detected, which addresses availability rather than capacity adjustment. Round robin is a traffic distribution method that cycles requests evenly across a set of servers, and like load balancing, manages traffic distribution rather than adjusting the number of available compute instances.', 'isMultiAnswer': False, 'domain_id': 3}, {'id': 'q087', 'question': 'Which of the following is a correct relationship between regions, Availability Zones, and edge locations?', 'options': {'A': 'Data centers contain regions', 'B': 'Regions contain Availability Zones', 'C': 'Availability Zones contain edge locations', 'D': 'Edge locations contain regions'}, 'answer': 'B', 'explanation': 'Regions are geographic areas that contain multiple Availability Zones. Each AZ consists of one or more data centers, and edge locations are separate points of presence used by CloudFront, independent of AZs.\nData centers contain regions reverses the hierarchy. Data centers sit inside AZs, which sit inside Regions. Availability Zones contain edge locations is false. Edge locations are separate infrastructure from AZs and exist independently across the globe. Edge locations contain regions is false. Edge locations are smaller points of presence and have no containing relationship with Regions.', 'isMultiAnswer': False, 'domain_id': 3}, {'id': 'q020', 'question': 'A startup company is operating on limited funds and is extremely concerned about cost overruns. Which of the below options can be used to notify the company when their monthly AWS bill exceeds $2000?', 'options': {'A': 'Set up a CloudWatch billing alarm that triggers an SNS notification when the threshold is exceeded', 'B': 'Configure Amazon Simple Email Service to send billing alerts to their email address on a daily basis', 'C': 'Configure AWS Budgets to alert the company when the threshold is exceeded', 'D': 'Configure AWS CloudTrail to automatically delete all AWS resources when the threshold is exceeded', 'E': 'Configure Amazon Connect to alert the company when the threshold is exceeded'}, 'answer': ['A', 'C'], 'explanation': 'A CloudWatch billing alarm triggers an SNS notification when costs exceed a set threshold, and AWS Budgets lets you set custom cost thresholds with automatic alerts. Both are native AWS tools for cost monitoring.\nAmazon Simple Email Service is an email sending service for transactional and marketing communications, and while it can send emails it does not natively monitor AWS billing or trigger alerts based on cost thresholds. AWS CloudTrail records API calls and account activity for auditing purposes, and has no capability to monitor billing thresholds or delete resources in response to cost events. Amazon Connect is a cloud contact center service for managing customer communications via voice and chat, and has no connection to AWS billing monitoring or cost threshold alerting.', 'isMultiAnswer': True, 'domain_id': 4}, {'id': 'q059', 'question': 'Which of the following BEST describe the AWS pricing model?', 'options': {'A': 'Fixed-term', 'B': 'Pay-as-you-go', 'C': 'Colocation', 'D': 'Planned', 'E': 'Variable cost'}, 'answer': ['B', 'E'], 'explanation': 'AWS pricing is pay-as-you-go and variable cost. There are no fixed terms required, no colocation fees, and no mandatory upfront plans.\nFixed-term pricing requires a commitment to a set contract duration, which is the opposite of the AWS pay-as-you-go model where usage can scale up or down at any time without contractual obligations. Colocation refers to housing customer-owned servers in a third-party data center, which is an on-premises model rather than a cloud pricing principle. Planned pricing implies predetermined usage schedules and costs, which contradicts the AWS model where customers pay based on actual consumption without mandatory advance planning.', 'isMultiAnswer': True, 'domain_id': 4}, {'id': 'q006', 'question': 'You have set up consolidated billing for several AWS accounts. One of the accounts has purchased a number of reserved instances for 3 years. Which of the following is true regarding this scenario?', 'options': {'A': 'The Reserved Instance discounts can only be shared with the master account', 'B': 'All accounts can receive the hourly cost benefit of the Reserved Instances', 'C': 'The purchased instances will have better performance than On-demand instances', 'D': 'There are no cost benefits from using consolidated billing; It is for informational purposes only'}, 'answer': 'B', 'explanation': 'With consolidated billing, Reserved Instance discounts are automatically shared across all accounts in the organization, so any account can benefit from the hourly cost savings.\nThe Reserved Instance discounts applying only to the master account is incorrect because consolidated billing specifically shares RI benefits across all member accounts in the organization, not just the account that purchased them. The claim that reserved instances have better performance than On-Demand instances is false because both run on the same underlying AWS infrastructure, and the Reserved Instance pricing model is a billing commitment rather than a different hardware tier. Consolidated billing does provide real cost benefits beyond purely organizational purposes, combining usage for volume discounts and sharing Reserved Instance savings across accounts, so the claim that it is for informational purposes only is incorrect.', 'isMultiAnswer': False, 'domain_id': 4}, {'id': 'q009', 'question': 'A company has an AWS Enterprise Support plan. They want quick and efficient guidance with their billing and account inquiries. Which of the following should the company use?', 'options': {'A': 'AWS Health Dashboard', 'B': 'AWS Support Concierge', 'C': 'AWS Customer Service', 'D': 'AWS Business Support'}, 'answer': 'B', 'explanation': 'The AWS Support Concierge, available exclusively on the Enterprise Support plan, is a dedicated team for billing and account inquiries, providing fast and personalized assistance.\nAWS Health Dashboard provides real-time and personalized alerts about AWS service events that may affect your resources, and is a service health monitoring tool rather than a billing or account support contact. AWS Customer Service handles general account and billing enquiries for all customers but does not provide the dedicated, personalized support that the Concierge team offers to Enterprise plan holders. AWS Business Support provides 24/7 access to Cloud Support Engineers for technical issues and includes Infrastructure Event Management for an additional fee, but does not include a dedicated Concierge team for billing and account guidance.', 'isMultiAnswer': False, 'domain_id': 4}, {'id': 'q016', 'question': 'Which of the following helps a customer view the Amazon EC2 billing activity for the past month?', 'options': {'A': 'AWS Budgets', 'B': 'AWS Pricing Calculator', 'C': 'AWS Systems Manager', 'D': 'AWS Cost & Usage Reports'}, 'answer': 'D', 'explanation': 'AWS Cost and Usage Reports provide the most detailed and comprehensive breakdown of actual AWS spending, including EC2 billing activity, by time period and resource.\nAWS Budgets lets you set custom cost and usage thresholds and receive alerts when those thresholds are exceeded, and is a cost governance and alerting tool rather than a service for reviewing historical billing activity. The AWS Pricing Calculator estimates future costs for AWS services before provisioning them, and does not provide reports on historical billing activity. AWS Systems Manager provides operational tools for managing and automating tasks across AWS infrastructure, and has no connection to billing reporting or cost analysis.', 'isMultiAnswer': False, 'domain_id': 4}, {'id': 'q017', 'question': 'What do you gain from setting up consolidated billing for five different AWS accounts under another master account?', 'options': {'A': "AWS services' costs will be reduced to half the original price", 'B': 'The consolidated billing feature is just for organizational purpose', 'C': 'Each AWS account gets volume discounts', 'D': 'Each AWS account gets five times the free-tier services capacity'}, 'answer': 'C', 'explanation': 'Consolidated billing aggregates usage across all accounts, which can push the combined usage into higher volume tiers and unlock volume discounts that individual accounts would not reach on their own.\nAWS services costs are not reduced to half the original price under consolidated billing. Volume discounts apply incrementally based on combined usage tiers and vary by service rather than applying a fixed 50% reduction. Consolidated billing provides genuine cost benefits beyond purely organizational purposes through volume discounts and Reserved Instance sharing, so the claim that it is purely organizational is incorrect. Each AWS account does not receive five times the free-tier services capacity under consolidated billing. The free tier applies per organization rather than per account, and consolidated billing does not multiply free-tier allowances.', 'isMultiAnswer': False, 'domain_id': 4}, {'id': 'q028', 'question': 'You want to run a questionnaire application for only one day (without interruption), which Amazon EC2 purchase option should you use?', 'options': {'A': 'Reserved instances', 'B': 'Spot instances', 'C': 'Dedicated instances', 'D': 'On-demand instances'}, 'answer': 'D', 'explanation': 'On-Demand instances let you run workloads for any duration without long-term commitments or interruptions, making them ideal for short, one-time tasks where continuous availability is required.\nReserved Instances require a minimum one-year commitment and are cost-effective for steady-state workloads running continuously over that period, making them a poor fit for a single-day task where the commitment term would far exceed the actual usage. Spot Instances use spare AWS capacity at a significant discount but can be interrupted by AWS at any time, making them unsuitable for a workload that must run for a full day without interruption. Dedicated Instances run on hardware dedicated to a single customer for compliance or licensing purposes, and while they provide isolation they are more expensive than standard On-Demand Instances and do not offer any advantage for a simple one-day task.', 'isMultiAnswer': False, 'domain_id': 4}, {'id': 'q029', 'question': 'You are working on a project that involves creating thumbnails of millions of images. Consistent uptime is not an issue, and continuous processing is not required. Which EC2 buying option would be the most cost-effective?', 'options': {'A': 'Reserved Instances', 'B': 'On-demand Instances', 'C': 'Dedicated Instances', 'D': 'Spot Instances'}, 'answer': 'D', 'explanation': 'Spot Instances use spare AWS capacity at steep discounts and are perfect for fault-tolerant batch jobs like image processing, where interruptions are acceptable and uptime is not critical.\nReserved Instances provide a significant discount over On-Demand pricing for steady-state workloads through a one or three-year commitment, but are not cost-effective for batch workloads that run only periodically and can tolerate interruptions. On-Demand Instances charge the full hourly rate with no discount, making them significantly more expensive than Spot Instances for a batch image processing workload where the timing is flexible. Dedicated Instances run on hardware dedicated to a single customer and are designed for compliance and licensing isolation requirements, not for cost optimization of batch processing workloads.', 'isMultiAnswer': False, 'domain_id': 4}], 'set_b': [{'id': 'q161', 'question': 'What are the benefits of developing and running a new application in the AWS Cloud compared to on-premises?', 'options': {'A': 'AWS automatically distributes the data globally for higher durability', 'B': 'AWS will take care of operating the application', 'C': 'AWS makes it easy to architect for high availability', 'D': 'AWS can easily accommodate application demand changes', 'E': 'AWS takes care of application security patching'}, 'answer': ['C', 'D'], 'explanation': "AWS makes it easy to architect for high availability using multi-AZ deployments, load balancers, and managed services, and the cloud's elasticity allows applications to scale up or down to match demand changes quickly.\nAWS does not automatically distribute all data globally by default, as data residency and replication are configuration choices the customer makes depending on the services and settings they select. AWS does not take care of operating the application, as customers remain responsible for deploying, managing, and maintaining their own application code and runtime environments. AWS does not take care of application security patching, as patching the application layer is the customer's responsibility under the Shared Responsibility Model.", 'isMultiAnswer': True, 'domain_id': 1}, {'id': 'q206', 'question': 'The principle “design for failure and nothing will fail” is very important when designing your AWS Cloud architecture. Which of the following would help adhere to this principle?', 'options': {'A': 'Multi-factor authentication', 'B': 'Availability Zones', 'C': 'Elastic Load Balancing', 'D': 'Penetration testing', 'E': 'Vertical Scaling'}, 'answer': ['B', 'C'], 'explanation': 'Deploying across multiple Availability Zones provides physical redundancy so that if one zone experiences a failure, instances in the remaining zones continue serving traffic without interruption. Elastic Load Balancing automatically detects unhealthy targets and routes traffic only to healthy ones, preventing a single failed instance from bringing down the entire application. Both directly implement the design-for-failure principle.\nMulti-factor authentication adds a second layer of security to account and user sign-in, and is an access security control with no bearing on fault tolerance or application resilience. Penetration testing simulates attacks against an application to identify security vulnerabilities, and is a security assessment practice rather than an architectural design approach for surviving component failures. Vertical scaling increases the capacity of a single instance by adding more CPU or memory, which creates a larger single point of failure rather than distributing risk, and is the opposite of the redundancy that design-for-failure requires.', 'isMultiAnswer': True, 'domain_id': 1}, {'id': 'q216', 'question': 'Which of the following are important design principles you should adopt when designing systems on AWS?', 'options': {'A': 'Always use Global Services in your architecture rather than Regional Services', 'B': 'Always choose to pay as you go', 'C': 'Treat servers as fixed resources', 'D': 'Automate wherever possible', 'E': 'Remove single points of failure'}, 'answer': ['D', 'E'], 'explanation': 'Automating wherever possible reduces manual errors and speeds recovery, and removing single points of failure through redundancy ensures continued operation if one component fails, both being core AWS design principles.\nAlways using Global Services rather than Regional Services is not a recognized design principle, as the choice between global and regional services depends on the specific workload requirements and is not a blanket architectural rule. Always choosing to pay as you go is a billing model characteristic rather than a system design principle, and pricing decisions are made based on cost optimization goals rather than architectural patterns. Treating servers as fixed resources contradicts the cloud design principle of elasticity, which calls for treating infrastructure as disposable and dynamically scalable rather than permanent and static.', 'isMultiAnswer': True, 'domain_id': 1}, {'id': 'q141', 'question': 'One of the advantages to moving infrastructure from an on-premises data center to the AWS Cloud is:', 'options': {'A': 'It allows the business to eliminate IT bills', 'B': "It allows the business to put a server in each customer's data center", 'C': 'It allows the business to focus on business activities', 'D': 'It allows the business to leave servers unpatched'}, 'answer': 'C', 'explanation': "By offloading infrastructure management to AWS, companies can redirect their IT staff and resources toward developing and improving their core products and services rather than maintaining data centers.\nAWS does not eliminate IT bills, as customers continue to pay for the services they consume under the pay-as-you-go model. Placing a server in each customer's data center describes an on-premises or edge deployment model, which is the opposite of migrating infrastructure to the cloud. Moving to AWS does not allow servers to go unpatched, as the Shared Responsibility Model still requires customers to patch the operating systems and applications running on their own instances.", 'isMultiAnswer': False, 'domain_id': 1}, {'id': 'q143', 'question': 'How can a user protect against AWS service disruptions if a natural disaster affects an entire geographic area?', 'options': {'A': 'Deploy applications across multiple Availability Zones within an AWS Region', 'B': 'Use a hybrid cloud computing deployment model within the geographic area', 'C': 'Deploy applications across multiple AWS Regions', 'D': 'Store application artifacts using AWS Artifact and replicate them across multiple AWS Regions'}, 'answer': 'C', 'explanation': 'A natural disaster affecting an entire geographic area could take down a whole AWS Region, so deploying across multiple Regions in different geographies ensures the application remains operational even if one Region becomes completely unavailable.\nDeploying across multiple Availability Zones within a single Region protects against isolated data center failures but does not provide protection if the entire Region and its surrounding geographic area is affected by a natural disaster. Using a hybrid cloud deployment model within the same geographic area keeps infrastructure in the affected zone, meaning a regional natural disaster would still disrupt both the on-premises and cloud components simultaneously. AWS Artifact is a portal for accessing AWS compliance reports and security documentation, not a storage or replication service, making this option factually incorrect as a disaster recovery strategy.', 'isMultiAnswer': False, 'domain_id': 1}, {'id': 'q148', 'question': 'Which disaster recovery scenario offers the lowest probability of down time?', 'options': {'A': 'Backup and restore', 'B': 'Pilot light', 'C': 'Warm standby', 'D': 'Multi-site active-active'}, 'answer': 'D', 'explanation': 'Multi-site active-active runs fully redundant live copies of your application across multiple sites simultaneously, so if one site fails the other immediately serves all traffic with essentially zero downtime.\nBackup and restore has the highest recovery time of all DR strategies. Data is restored from backups after a failure, meaning significant downtime is expected. Pilot light keeps a minimal version of the environment running and scales up during a disaster, resulting in a short but non-zero recovery time. Warm standby runs a scaled-down but fully functional version of the environment, which requires scaling up before handling full traffic load.', 'isMultiAnswer': False, 'domain_id': 1}, {'id': 'q156', 'question': 'What is a value proposition of the AWS Cloud?', 'options': {'A': 'AWS is responsible for security in the AWS Cloud', 'B': 'No long-term contract is required', 'C': 'Provision new servers in days', 'D': 'AWS manages user applications in the AWS Cloud'}, 'answer': 'B', 'explanation': "No long-term contract is required because AWS uses a pay-as-you-go model, allowing customers to use services on demand and stop at any time without upfront commitments or termination penalties.\nAWS is responsible for security in the cloud is a partial truth that misrepresents the Shared Responsibility Model. Security is shared, with AWS responsible for the infrastructure and customers responsible for their data and configurations. Provision new servers in days is inaccurate. One of AWS's key advantages is provisioning resources in minutes, not days, which is the reality that distinguishes cloud from traditional procurement. AWS manages user applications in the AWS Cloud is false. Application management remains the customer's responsibility under the Shared Responsibility Model.", 'isMultiAnswer': False, 'domain_id': 1}, {'id': 'q174', 'question': 'Which AWS Cloud benefit eliminates the need for users to try estimating future infrastructure usage?', 'options': {'A': 'Easy and fast deployment of applications in multiple Regions around the world', 'B': 'Security of the AWS Cloud', 'C': 'Elasticity of the AWS Cloud', 'D': 'Lower variable costs due to massive economies of scale'}, 'answer': 'C', 'explanation': "Cloud elasticity allows resources to scale up or down on demand, eliminating the need to predict and provision for peak future capacity in advance.\nEasy and fast deployment of applications in multiple Regions is a benefit of AWS's global infrastructure, enabling speed and reach, but does not remove the need to estimate future infrastructure usage. Security of the AWS Cloud refers to the protections AWS provides for its infrastructure under the shared responsibility model, which is unrelated to capacity planning or infrastructure estimation. Lower variable costs due to massive economies of scale means AWS can offer reduced pricing as its customer base grows, but lower costs do not eliminate the underlying need to estimate how much infrastructure will be required.", 'isMultiAnswer': False, 'domain_id': 1}, {'id': 'q187', 'question': 'How can the AWS Cloud increase user workforce productivity after migration from an on-premises data center?', 'options': {'A': 'Users do not have to wait for infrastructure provisioning', 'B': 'The AWS Cloud infrastructure is much faster than an on-premises data center infrastructure', 'C': 'AWS takes over application configuration management on behalf of users', 'D': 'Users do not need to address security and compliance issues'}, 'answer': 'A', 'explanation': "With AWS, developers and engineers can self-provision infrastructure in minutes through the console or APIs, eliminating the waiting time associated with traditional hardware procurement and setup.\nThe AWS Cloud infrastructure is much faster than an on-premises data center infrastructure is misleading. The productivity gain comes from removing provisioning delays, not from raw infrastructure speed. AWS takes over application configuration management on behalf of users is false. Application configuration remains the customer's responsibility under the Shared Responsibility Model. Users do not need to address security and compliance issues is false. Customers remain responsible for security in the cloud, including their applications, data, and access controls.", 'isMultiAnswer': False, 'domain_id': 1}, {'id': 'q189', 'question': 'What is an example of agility in the AWS Cloud?', 'options': {'A': 'Access to multiple instance types', 'B': 'Access to managed services', 'C': 'Using Consolidated Billing to produce one bill', 'D': 'Decreased acquisition time for new compute resources'}, 'answer': 'D', 'explanation': 'Agility in the AWS Cloud is best illustrated by the dramatically reduced time to acquire and provision new compute resources, from weeks on-premises to minutes in the cloud, enabling teams to experiment and iterate faster.\nAccess to multiple instance types is a flexibility benefit that allows customers to match compute to workload requirements, but does not directly describe the speed of acquiring new resources. Access to managed services reduces operational overhead by offloading infrastructure management to AWS, but is an example of reduced complexity rather than agility. Consolidated Billing is a cost management feature that combines charges from multiple accounts into a single bill, which is a billing convenience and unrelated to the speed of resource acquisition.', 'isMultiAnswer': False, 'domain_id': 1}, {'id': 'q203', 'question': 'Which of the below is a best-practice when designing solutions on AWS?', 'options': {'A': 'Invest heavily in architecting your environment, as it is not easy to change your design later', 'B': 'Use AWS reservations to reduce costs when testing your production environment', 'C': 'Automate wherever possible to make architectural experimentation easier', 'D': 'Provision a large compute capacity to handle any spikes in load'}, 'answer': 'C', 'explanation': 'AWS best practice is to automate infrastructure and deployment wherever possible, which makes architectural experimentation faster and reduces human error.\nInvesting heavily in upfront architectural design contradicts the cloud principle that infrastructure should be treated as flexible and changeable, with automation enabling rapid iteration rather than requiring heavy planning before deployment. Using AWS reservations to reduce costs when testing production environments misapplies Reserved Instances, which are a billing commitment for predictable steady-state workloads rather than a cost reduction tool for testing environments. Provisioning large compute capacity to handle any spikes in load describes over-provisioning, which is an on-premises anti-pattern that cloud best practices replace with elastic scaling that dynamically matches capacity to actual demand.', 'isMultiAnswer': False, 'domain_id': 1}, {'id': 'q215', 'question': 'Which of the following is one of the benefits of moving infrastructure from an on-premises data center to AWS?', 'options': {'A': 'Free support for all enterprise customers', 'B': 'Automatic data protection', 'C': 'Reduced Capital Expenditure (CapEx)', 'D': 'AWS holds responsibility for managing customer applications'}, 'answer': 'C', 'explanation': 'Migrating from on-premises to AWS converts large upfront capital expenditures such as purchasing and maintaining physical hardware into smaller variable operational expenses, directly reducing CapEx and improving financial flexibility.\nAWS does not provide free support to all enterprise customers, as support is available through paid tiers ranging from Developer to Enterprise, with costs varying by plan. AWS does not automatically protect data on behalf of customers, as data protection responsibilities such as encryption and backup configuration remain with the customer under the Shared Responsibility Model. AWS does not manage customer applications, as application-layer responsibilities including code, configuration, and runtime management remain with the customer regardless of which infrastructure services they use.', 'isMultiAnswer': False, 'domain_id': 1}, {'id': 'q227', 'question': 'Which statement best describes the operational excellence pillar of the AWS Well-Architected Framework?', 'options': {'A': 'The ability of a system to recover gracefully from failure', 'B': 'The efficient use of computing resources to meet requirements', 'C': 'The ability to monitor systems and improve supporting processes and procedures', 'D': 'The ability to manage datacenter operations more efficiently'}, 'answer': 'C', 'explanation': 'The Operational Excellence pillar of the AWS Well-Architected Framework focuses on running and monitoring workloads effectively, continuously improving processes, and automating operations to deliver business value.\nThe ability of a system to recover gracefully from failure describes the Reliability pillar, which focuses on workload availability and the ability to recover from disruptions. The efficient use of computing resources to meet requirements describes the Performance Efficiency pillar, which focuses on using the right resource types and sizes to match workload demands. Managing datacenter operations more efficiently does not correspond to any Well-Architected pillar, as AWS manages all physical datacenter infrastructure on behalf of customers and this is not a customer concern in the cloud.', 'isMultiAnswer': False, 'domain_id': 1}, {'id': 'q242', 'question': 'Jessica is managing an e-commerce web application in AWS. The application is hosted on six EC2 instances. One day, three of the instances crashed; but none of her customers were affected. What has Jessica done correctly in this scenario?', 'options': {'A': 'She has properly built an elastic system', 'B': 'She has properly built a fault tolerant system', 'C': 'She has properly built an encrypted system', 'D': 'She has properly built a scalable system'}, 'answer': 'B', 'explanation': 'A fault-tolerant system is designed to continue operating correctly even when some of its components fail, which is exactly what the scenario describes: three of six instances crashed but no customers were affected.\nAn elastic system automatically scales capacity up or down in response to changes in demand, but elasticity does not address continued operation during component failure. An encrypted system protects data from unauthorised access through cryptographic controls, which is a security property unrelated to maintaining availability when instances crash. A scalable system is designed to handle growth in workload or users by adding resources, but scalability does not ensure the application keeps running when existing instances fail.', 'isMultiAnswer': False, 'domain_id': 1}, {'id': 'q253', 'question': 'Using Amazon EC2 falls under which of the following cloud computing models?', 'options': {'A': 'IaaS & SaaS', 'B': 'IaaS', 'C': 'SaaS', 'D': 'PaaS'}, 'answer': 'B', 'explanation': 'Amazon EC2 is IaaS because AWS provides the virtualized compute infrastructure while the customer manages the operating system, middleware, and applications above it.\nIaaS and SaaS combined is not a recognized classification for any single service, as each service falls under one model rather than spanning two. SaaS delivers fully managed software applications to end users with no infrastructure or platform management required, whereas EC2 requires customers to manage everything above the hypervisor. PaaS provides a managed platform where customers deploy application code without managing the underlying infrastructure, whereas EC2 gives customers direct control over the operating system and runtime environment.', 'isMultiAnswer': False, 'domain_id': 1}, {'id': 'q254', 'question': 'Which of the below is a best-practice when building applications on AWS?', 'options': {'A': 'Strengthen physical security by applying the principle of least privilege', 'B': 'Ensure that the application runs on hardware from trusted vendors', 'C': 'Use IAM policies to maintain performance', 'D': 'Decouple the components of the application so that they run independently'}, 'answer': 'D', 'explanation': 'Decoupling application components so they communicate through well-defined interfaces such as APIs or queues rather than direct dependencies means each component can scale, fail, and be updated independently without causing cascading failures throughout the application.\nApplying the principle of least privilege is a security best practice for controlling access permissions, and while important, it relates to identity and access management rather than application architecture design. Ensuring that applications run on hardware from trusted vendors is not a customer concern on AWS, as AWS manages all underlying physical infrastructure and hardware selection on behalf of the customer. IAM policies are used to define access permissions for users and roles, and are an identity and access management tool rather than a mechanism for maintaining application performance.', 'isMultiAnswer': False, 'domain_id': 1}, {'id': 'q060', 'question': 'Under the shared responsibility model, which of the following tasks are the responsibility of the AWS customer?', 'options': {'A': 'Ensuring that application data is encrypted at rest', 'B': 'Ensuring that AWS NTP servers are set to the correct time', 'C': 'Ensuring that users have received security training in the use of AWS services', 'D': 'Ensuring that access to data centers is restricted', 'E': 'Ensuring that hardware is disposed of properly'}, 'answer': ['A', 'C'], 'explanation': "Customers are responsible for encrypting their application data at rest and for training their users on proper security practices when using AWS services, both sitting on the customer side of the model.\nEnsuring that AWS NTP servers are set to the correct time is entirely AWS's responsibility, as customers have no access to or control over the underlying infrastructure components that provide time synchronisation. Ensuring that access to data centers is restricted is entirely AWS's responsibility, covering physical access controls, surveillance, and protection of the facilities that house AWS infrastructure. Ensuring that hardware is disposed of properly is entirely AWS's responsibility, as customers never take possession of physical hardware and AWS manages all end-of-life processes for its own equipment.", 'isMultiAnswer': True, 'domain_id': 2}, {'id': 'q078', 'question': 'Which AWS services can be used to gather information about AWS account activity?', 'options': {'A': 'Amazon CloudFront', 'B': 'AWS Cloud9', 'C': 'AWS CloudTrail', 'D': 'AWS CloudHSM', 'E': 'Amazon CloudWatch'}, 'answer': ['C', 'E'], 'explanation': 'AWS CloudTrail logs all API calls and account activity across an AWS account, providing a complete audit trail of who did what and when. Amazon CloudWatch collects metrics, logs, and event data from AWS services and resources, providing operational visibility into account activity and performance.\nAmazon CloudFront is a content delivery network that caches and distributes content to users at edge locations worldwide, and does not gather information about account activity. AWS Cloud9 is a cloud-based integrated development environment for writing, running, and debugging code, and has no account monitoring or activity logging capability. AWS CloudHSM is a hardware security module service that manages and stores cryptographic keys in dedicated hardware, and is not a tool for monitoring or gathering information about account activity.', 'isMultiAnswer': True, 'domain_id': 2}, {'id': 'q103', 'question': 'Which of the following will enhance the security of access to the AWS Management Console?', 'options': {'A': 'AWS Secrets Manager', 'B': 'AWS Certificate Manager', 'C': 'AWS Multi-Factor Authentication (AWS MFA)', 'D': 'Security groups', 'E': 'Password policies'}, 'answer': ['C', 'E'], 'explanation': 'MFA adds a second authentication factor beyond a password to protect console logins, and password policies enforce complexity and rotation requirements. Both directly enhance the security of access to the AWS Management Console.\nAWS Secrets Manager stores, rotates, and manages access to secrets such as database credentials and API keys, and is a credentials management service rather than a mechanism for enhancing the authentication security of the AWS Management Console itself. AWS Certificate Manager provisions and manages SSL/TLS certificates for encrypting data in transit between applications and users, and has no role in controlling or securing console login access. Security groups act as virtual firewalls that control inbound and outbound network traffic at the EC2 instance level, and operate at the network layer rather than the console authentication layer.', 'isMultiAnswer': True, 'domain_id': 2}, {'id': 'q107', 'question': 'Which of the following common IT tasks can AWS cover to free up company IT resources?', 'options': {'A': 'Patching database software', 'B': 'Testing application releases', 'C': 'Backing up databases', 'D': 'Creating database schema', 'E': 'Running penetration tests'}, 'answer': ['A', 'C'], 'explanation': "Patching database software and backing up databases are maintenance tasks that AWS handles automatically for managed services such as RDS, freeing up customers' IT resources from these time-consuming operational responsibilities.\nTesting application releases is the customer's responsibility as it requires knowledge of the specific application logic, acceptance criteria, and business requirements that only the customer possesses, making it a task AWS cannot cover on the customer's behalf. Creating database schema requires understanding of the customer's data model and application requirements, and is a design and development activity that the customer must perform rather than a managed service task AWS provides. Running penetration tests is a security activity that customers perform on their own applications and infrastructure, and is not an operational burden AWS covers as part of its managed service offerings.", 'isMultiAnswer': True, 'domain_id': 2}, {'id': 'q105', 'question': 'For which auditing process does AWS have sole responsibility?', 'options': {'A': 'AWS IAM policies', 'B': 'Physical security', 'C': 'Amazon S3 bucket policies', 'D': 'AWS CloudTrail Logs'}, 'answer': 'B', 'explanation': "Under the shared responsibility model, AWS has sole responsibility for physical security of its data centers, including controls such as perimeter security, surveillance, and hardware disposal, as customers never have access to AWS physical facilities.\nAWS IAM policies define permissions for users, groups, and roles within an AWS account, and creating, managing, and auditing these policies is entirely the customer's responsibility as they reflect each customer's own access control decisions. Amazon S3 bucket policies control access to objects stored within S3 buckets, and configuring and auditing these policies is the customer's responsibility as they govern how the customer's own data is accessed and shared. AWS CloudTrail logs record API calls and account activity across an AWS environment, and while CloudTrail is an AWS-managed service, enabling it, configuring log retention, and auditing the logs it produces are all customer responsibilities.", 'isMultiAnswer': False, 'domain_id': 2}, {'id': 'q117', 'question': 'Which of the following Identity and Access Management (IAM) entities is associated with an access key ID and secret access key when using AWS Command Line Interface (AWS CLI)?', 'options': {'A': 'IAM group', 'B': 'IAM user', 'C': 'IAM role', 'D': 'IAM policy'}, 'answer': 'B', 'explanation': 'IAM users are the entities that have access keys consisting of an access key ID and secret access key associated with them for programmatic CLI access to AWS services.\nAn IAM group is a collection of IAM users used to manage shared permissions collectively, and is not an identity that can authenticate or be issued access keys of any kind. An IAM role uses temporary security credentials that are automatically issued and rotated when the role is assumed, and does not have permanent access keys associated with it. An IAM policy is a JSON document that defines permissions by specifying allowed or denied actions on resources, and is a permissions construct rather than an identity that can hold or be associated with access keys.', 'isMultiAnswer': False, 'domain_id': 2}, {'id': 'q118', 'question': 'Under the shared responsibility model, which of the following is the customer responsible for?', 'options': {'A': 'Ensuring that disk drives are wiped after use', 'B': 'Ensuring that firmware is updated on hardware devices', 'C': 'Ensuring that data is encrypted at rest', 'D': 'Ensuring that network cables are category six or higher'}, 'answer': 'C', 'explanation': "Data encryption at rest is a customer responsibility. AWS provides the tools and services to enable encryption, but customers decide whether and how to encrypt their data.\nEnsuring disk drives are wiped after use is AWS's responsibility. AWS handles the secure decommissioning and disposal of physical storage hardware. Ensuring firmware is updated on hardware devices is AWS's responsibility. Customers have no access to or control over physical hardware. Ensuring network cables are category six or higher is AWS's responsibility. Physical networking infrastructure is managed entirely by AWS.", 'isMultiAnswer': False, 'domain_id': 2}, {'id': 'q121', 'question': 'Which of the following is a shared control between the customer and AWS?', 'options': {'A': 'Providing a key for Amazon S3 client-side encryption', 'B': 'Configuration of an Amazon EC2 instance', 'C': 'Environmental controls of physical AWS data centers', 'D': 'Awareness'}, 'answer': 'D', 'explanation': "Awareness and training is a shared control because both AWS and the customer must independently ensure their own staff understand their respective security responsibilities, regardless of what the other party does.\nProviding a key for Amazon S3 client-side encryption is solely the customer's responsibility, as AWS has no involvement in client-side key generation or management. Configuration of an Amazon EC2 instance is solely the customer's responsibility, as customers control the guest OS and everything installed on it. Environmental controls of physical AWS data centers are solely AWS's responsibility, as customers have no access to or involvement in physical facility management.", 'isMultiAnswer': False, 'domain_id': 2}, {'id': 'q144', 'question': 'Which activity is a customer responsibility in the AWS Cloud according to the AWS shared responsibility model?', 'options': {'A': 'Ensuring network connectivity from AWS to the internet', 'B': 'Patching and fixing flaws within the AWS Cloud infrastructure', 'C': 'Ensuring the physical security of cloud data centers', 'D': 'Ensuring Amazon EBS volumes are backed up'}, 'answer': 'D', 'explanation': "Under the Shared Responsibility Model, backing up EBS volumes through snapshots is the customer's responsibility, as AWS does not automatically back up EBS volumes on the customer's behalf.\nEnsuring network connectivity from AWS to the internet is entirely AWS's responsibility, as AWS manages and maintains the underlying network infrastructure that connects its services to the public internet. Patching and fixing flaws within the AWS Cloud infrastructure is entirely AWS's responsibility, as customers have no access to the underlying hardware, hypervisors, or physical networking components. Ensuring the physical security of cloud data centers is entirely AWS's responsibility, covering access controls, surveillance, and protection of the facilities that house AWS infrastructure.", 'isMultiAnswer': False, 'domain_id': 2}, {'id': 'q162', 'question': 'Which of the following services falls under the responsibility of the customer to maintain operating system configuration, security patching, and networking?', 'options': {'A': 'Amazon RDS', 'B': 'Amazon EC2', 'C': 'Amazon ElastiCache', 'D': 'AWS Fargate'}, 'answer': 'B', 'explanation': "With Amazon EC2, the customer is responsible for the guest operating system including configuration, security patching, and networking setup, as AWS only manages the underlying physical infrastructure.\nAmazon RDS is a fully managed relational database service where AWS handles operating system patching, database engine updates, and infrastructure maintenance on the customer's behalf. Amazon ElastiCache is a fully managed in-memory caching service where AWS manages the underlying operating system and infrastructure, removing those responsibilities from the customer entirely. AWS Fargate is a serverless compute engine for containers where AWS manages the underlying infrastructure and operating system, meaning the customer only needs to manage their container images and application code.", 'isMultiAnswer': False, 'domain_id': 2}, {'id': 'q169', 'question': 'A Cloud Practitioner must determine if any security groups in an AWS account have been provisioned to allow unrestricted access for specific ports. What is the SIMPLEST way to do this?', 'options': {'A': 'Review the inbound rules for each security group in the Amazon EC2 management console to check for port 0.0.0.0/0', 'B': 'Run AWS Trusted Advisor and review the findings', 'C': 'Open the AWS IAM console and check the inbound rule filters for open access', 'D': 'In AWS Config, create a custom rule that invokes an AWS Lambda function to review firewall rules for inbound access'}, 'answer': 'B', 'explanation': "AWS Trusted Advisor automatically scans your account and flags security groups with unrestricted access (0.0.0.0/0) to specific ports as part of its Security category checks, making it the simplest and most direct approach without manual investigation.\nManually reviewing inbound rules for each security group in the EC2 console to look for 0.0.0.0/0 entries would work but is time-consuming and error-prone at scale, making it far less simple than using Trusted Advisor's automated check. The AWS IAM console manages identities, users, roles, and permissions, and does not contain security group configurations or inbound traffic rules, making it the wrong place to check for unrestricted port access. Creating a custom AWS Config rule that invokes a Lambda function to review firewall rules would provide automated ongoing compliance checks but requires significant setup effort, making it far more complex than running the existing Trusted Advisor check.", 'isMultiAnswer': False, 'domain_id': 2}, {'id': 'q175', 'question': 'What can users access from AWS Artifact?', 'options': {'A': 'AWS security and compliance documents', 'B': 'A download of configuration management details for all AWS resources', 'C': 'Training materials for AWS services', 'D': 'A security assessment of the applications deployed in the AWS Cloud'}, 'answer': 'A', 'explanation': 'AWS Artifact is a self-service portal that provides on-demand access to AWS security and compliance documents such as SOC reports, ISO certifications, PCI attestations, and other auditor-issued compliance materials.\nConfiguration management details are not available from Artifact; AWS Config tracks resource configuration history and CloudTrail logs API activity, but neither is reached through Artifact. Training materials come from AWS Training and Certification and AWS Skill Builder, not Artifact, which holds only compliance documents. A security assessment of deployed applications is performed by Amazon Inspector, which scans EC2 instances and container images for vulnerabilities, not by Artifact.', 'isMultiAnswer': False, 'domain_id': 2}, {'id': 'q179', 'question': 'Which of the following can limit Amazon Simple Storage Service (Amazon S3) bucket access to specific users?', 'options': {'A': 'A public and private key-pair', 'B': 'Amazon Inspector', 'C': 'AWS Identity and Access Management (IAM) policies', 'D': 'Security Groups'}, 'answer': 'C', 'explanation': 'IAM policies can be applied directly to IAM users or groups to control exactly who can access an S3 bucket and what operations they can perform, providing fine-grained access control that limits access to specific users.\nSigning in with AWS account credentials provides root-level access to all S3 buckets by default rather than limiting access to specific users; root credentials should never be used for day-to-day access and do not restrict bucket access to particular individuals. Enabling S3 versioning preserves multiple versions of objects to protect against accidental deletion, and is a data recovery feature rather than an access restriction mechanism that limits which users can access the bucket. Setting a bucket policy to make the bucket private removes public access, but without specifying allowed principals it does not grant access to any specific users; additional policy statements identifying particular IAM principals are required to limit access to specific users.', 'isMultiAnswer': False, 'domain_id': 2}, {'id': 'q182', 'question': 'Which of the following tasks is the responsibility of AWS?', 'options': {'A': 'Encrypting client-side data', 'B': 'Configuring AWS Identity and Access Management (IAM) roles', 'C': 'Securing the Amazon EC2 hypervisor', 'D': 'Setting user password policies'}, 'answer': 'C', 'explanation': "Under the shared responsibility model, AWS is responsible for securing the underlying hypervisor that runs EC2 virtual machines, as this forms part of the infrastructure layer that customers have no access to or control over.\nEncrypting client-side data is the customer's responsibility, as AWS has no involvement in data that is encrypted before being sent to AWS services. Configuring IAM roles is the customer's responsibility, as customers define and manage the permissions that control what actions users and services can perform within their account. Setting user password policies is the customer's responsibility, as customers control the IAM password policies that govern how their users authenticate to the AWS Management Console.", 'isMultiAnswer': False, 'domain_id': 2}, {'id': 'q190', 'question': 'Which AWS security service protects applications from distributed denial of service attacks with always-on detection and automatic inline mitigations?', 'options': {'A': 'Amazon Inspector', 'B': 'AWS Web Application Firewall (AWS WAF)', 'C': 'Elastic Load Balancing (ELB)', 'D': 'AWS Shield'}, 'answer': 'D', 'explanation': 'AWS Shield provides always-on DDoS protection at no extra cost for all AWS customers, automatically detecting and mitigating the most common volumetric and protocol-based DDoS attacks without any customer configuration.\nAWS WAF is a web application firewall that filters application-layer HTTP and HTTPS traffic based on configurable rules, and while it helps mitigate application-layer attacks, it is a separate service from Shield and requires customer configuration rather than providing automatic always-on protection. Amazon GuardDuty is a threat detection service that uses machine learning to identify malicious activity and anomalous behavior in AWS accounts, and is an alerting and detection service rather than a service that actively blocks DDoS traffic. AWS CloudTrail records API calls and management events for auditing and compliance purposes, and has no capability to detect or protect against distributed denial of service attacks.', 'isMultiAnswer': False, 'domain_id': 2}, {'id': 'q200', 'question': 'What is the AWS feature that provides an additional level of security above the default authentication mechanism of usernames and passwords?', 'options': {'A': 'Encrypted keys', 'B': 'Email verification', 'C': 'AWS KMS', 'D': 'AWS MFA'}, 'answer': 'D', 'explanation': 'AWS Multi-Factor Authentication adds a second layer of security by requiring a one-time code from a hardware or virtual device in addition to a username and password, providing an additional level of security above the default username and password mechanism.\nEncrypted keys refer to cryptographic keys used for data encryption purposes such as those managed by AWS KMS, and while they protect stored data, they do not provide an additional authentication mechanism for user login security. Email verification is used to confirm ownership of an email address during account setup or password recovery flows, and is not an ongoing additional security layer applied on top of username and password for AWS console logins. AWS KMS is a key management service for creating and managing cryptographic keys used to encrypt data at rest and in transit, and does not add authentication factors to the login process.', 'isMultiAnswer': False, 'domain_id': 2}, {'id': 'q204', 'question': 'According to the AWS Acceptable Use Policy, which of the following statements is true regarding penetration testing of EC2 instances?', 'options': {'A': 'Penetration testing is not allowed in AWS', 'B': 'Penetration testing is performed automatically by AWS to determine vulnerabilities in your AWS infrastructure', 'C': 'Penetration testing can be performed by the customer on their own instances without prior authorization from AWS', 'D': 'The AWS customers are only allowed to perform penetration testing on services managed by AWS'}, 'answer': 'C', 'explanation': "AWS's Acceptable Use Policy allows customers to perform penetration testing on their own EC2 instances and certain other permitted services without prior authorisation from AWS, provided the testing complies with the AUP conditions.\nPenetration testing is not prohibited in AWS; the Acceptable Use Policy explicitly permits customers to conduct penetration testing on their own resources within defined guidelines, making the claim that it is not allowed incorrect. AWS does not perform automated penetration testing on behalf of customers; Amazon Inspector performs automated security assessments for vulnerabilities and network exposure, but this is not the same as penetration testing, and AWS does not conduct adversarial testing of customer infrastructure. AWS customers are permitted to perform penetration testing on their own services and resources, not only on services managed by AWS; the restriction is that testing must target the customer's own resources rather than AWS shared infrastructure.", 'isMultiAnswer': False, 'domain_id': 2}, {'id': 'q213', 'question': 'What is the AWS service that enables you to manage all of your AWS accounts from a single master account?', 'options': {'A': 'AWS WAF', 'B': 'AWS Trusted Advisor', 'C': 'AWS Organizations', 'D': 'AWS Config'}, 'answer': 'C', 'explanation': 'AWS Organizations enables you to create a hierarchy of AWS accounts managed from a single master account, applying policies and consolidated billing across all member accounts.\nAWS WAF is a web application firewall that filters and blocks malicious web traffic using managed and custom rule sets, and has no role in managing multiple AWS accounts. AWS Trusted Advisor analyzes your AWS environment and provides recommendations across cost optimization, security, and performance, but does not provide centralized management of multiple accounts. AWS Config continuously monitors and records AWS resource configurations for compliance purposes, but operates within individual accounts rather than providing centralized multi-account management.', 'isMultiAnswer': False, 'domain_id': 2}, {'id': 'q219', 'question': 'Which of the following services can help protect your web applications from SQL injection and other vulnerabilities in your application code?', 'options': {'A': 'Amazon Cognito', 'B': 'AWS IAM', 'C': 'Amazon Aurora', 'D': 'AWS WAF'}, 'answer': 'D', 'explanation': 'AWS WAF is a web application firewall that lets you create rules to inspect and filter HTTP and HTTPS traffic, blocking common web exploits such as SQL injection and cross-site scripting before they reach your application.\nAmazon Cognito is a user identity and authentication service for web and mobile applications that handles user sign-up, sign-in, and access control for application users, and does not inspect or filter HTTP traffic for SQL injection or other web exploits. AWS IAM manages user permissions and access to AWS services and resources, and is an identity and access management service rather than a traffic inspection tool that can block malicious web requests. Amazon Aurora is a relational database service compatible with MySQL and PostgreSQL, and is a managed database offering rather than a security service for filtering web application traffic.', 'isMultiAnswer': False, 'domain_id': 2}, {'id': 'q063', 'question': 'Which AWS services should be used for read/write of constantly changing data?', 'options': {'A': 'Amazon S3 GLACIER', 'B': 'Amazon RDS', 'C': 'AWS Snowball', 'D': 'Amazon Redshift', 'E': 'Amazon EFS'}, 'answer': ['B', 'E'], 'explanation': 'Amazon RDS supports frequent read/write operations on relational data with full ACID transaction support, making it well suited for applications with constantly changing structured data. Amazon EFS provides a shared network file system with concurrent read/write access for multiple EC2 instances, making it appropriate for workloads that require continuous file-level changes.\nAmazon S3 Glacier is an archival storage service designed for data that is rarely accessed and does not support the frequent read/write operations that constantly changing data requires. AWS Snowball is a physical device used to transfer large volumes of data into or out of AWS and has no capability to serve as a read/write data store for active workloads. Amazon Redshift is a data warehouse service optimized for running complex analytical queries across large datasets, not for handling frequent transactional read/write operations on constantly changing data.', 'isMultiAnswer': True, 'domain_id': 3}, {'id': 'q089', 'question': 'Which AWS services can host a Microsoft SQL Server database?', 'options': {'A': 'Amazon EC2', 'B': 'Amazon Relational Database Service (Amazon RDS)', 'C': 'Amazon Aurora', 'D': 'Amazon Redshift', 'E': 'Amazon S3'}, 'answer': ['A', 'B'], 'explanation': 'Microsoft SQL Server can be hosted on Amazon EC2 instances where the customer installs and manages the database themselves, or via Amazon RDS for SQL Server where AWS manages the underlying infrastructure, patching, and backups as a fully managed service.\nAmazon Aurora supports MySQL and PostgreSQL-compatible database engines only and does not support Microsoft SQL Server. Amazon Redshift is a data warehouse service optimized for analytical queries on large datasets, not a relational database engine for hosting SQL Server workloads. Amazon S3 is an object storage service and cannot host or run a relational database engine.', 'isMultiAnswer': True, 'domain_id': 3}, {'id': 'q138', 'question': 'What can AWS edge locations be used for?', 'options': {'A': 'Hosting applications', 'B': 'Delivering content closer to users', 'C': 'Running NoSQL database caching services', 'D': 'Reducing traffic on the server by caching responses', 'E': 'Sending notification messages to end users'}, 'answer': ['B', 'D'], 'explanation': 'Edge locations deliver cached content geographically close to end users to reduce latency, and they absorb repeated requests by serving cached responses so that fewer requests reach the origin server.\nHosting applications compute resources for running applications are provided by EC2 instances and other services in AWS Regions and Availability Zones, not at edge locations. Running NoSQL database caching services managed database and caching services such as DynamoDB and ElastiCache run in Regions, not at edge locations. Sending notification messages to end users message delivery to end users is handled by services like Amazon SNS, which operates from Regional endpoints, not edge locations.', 'isMultiAnswer': True, 'domain_id': 3}, {'id': 'q168', 'question': 'A company wants to migrate its applications to a VPC on AWS. These applications will need to access on-premises resources. What combination of actions will enable the company to accomplish this goals?', 'options': {'A': 'Use the AWS Service Catalog to identify a list of on-premises resources that can be migrated', 'B': 'Build a VPN connection between an on-premises device and a virtual private gateway in the new VPC', 'C': 'Use Amazon Athena to query data from the on-premises database servers', 'D': "Connect the company's on-premises data center to AWS using AWS Direct Connect", 'E': "Leverage Amazon CloudFront to restrict access to static web content provided through the company's on-premises web servers"}, 'answer': ['B', 'D'], 'explanation': 'A site-to-site VPN through a virtual private gateway provides an encrypted tunnel over the internet between on-premises and the VPC, and AWS Direct Connect provides a dedicated private network link, both extending the on-premises network into AWS.\nAWS Service Catalog is a tool for managing and provisioning approved IT service portfolios within an organization, and has no capability to identify or connect on-premises resources to a VPC. Amazon Athena is a serverless query service that analyzes data stored in Amazon S3, and cannot query data directly from on-premises database servers. Amazon CloudFront is a content delivery network that caches and distributes content globally, and is not a mechanism for restricting or routing access between on-premises servers and a VPC.', 'isMultiAnswer': True, 'domain_id': 3}, {'id': 'q088', 'question': 'What approach to transcoding a large number of individual video files adheres to AWS architecture principles?', 'options': {'A': 'Using many instances in parallel', 'B': 'Using a single large instance during off-peak hours', 'C': 'Using dedicated hardware', 'D': 'Using a large GPU instance type'}, 'answer': 'A', 'explanation': 'Using many instances in parallel applies horizontal scaling, a core AWS architecture principle that distributes workloads across multiple instances simultaneously for greater speed and cost efficiency than sequential processing.\nUsing a single large instance during off-peak hours applies vertical scaling and sequential processing, which contradicts AWS architecture principles favoring parallelism and does not reduce total processing time. Using dedicated hardware provides physical server isolation for compliance or licensing requirements but does not improve throughput for large-scale parallel workloads. Using a large GPU instance type optimizes for graphics processing performance on a single instance rather than distributing the workload across multiple parallel instances.', 'isMultiAnswer': False, 'domain_id': 3}, {'id': 'q093', 'question': 'What time-savings advantage is offered with the use of Amazon Rekognition?', 'options': {'A': 'Amazon Rekognition provides automatic watermarking of images', 'B': 'Amazon Rekognition provides automatic detection of objects appearing in pictures', 'C': 'Amazon Recognition provides the ability to resize millions of images automatically', 'D': 'Amazon Rekognition uses Amazon Mechanical Turk to allow humans to bid on object detection jobs'}, 'answer': 'B', 'explanation': 'Amazon Rekognition automatically analyzes images and videos to detect objects, scenes, faces, text, and activities using machine learning, eliminating the time that would otherwise be spent on manual image review or building custom ML pipelines.\nAutomatic watermarking of images is not a feature of Amazon Rekognition, which is an analysis and detection service rather than an image editing or rights management tool. Resizing millions of images automatically is not a Rekognition capability and describes an image processing task better suited to a custom solution or a service like AWS Lambda with an image library. Amazon Rekognition does not use Amazon Mechanical Turk or involve human bidding on jobs, as its detection capabilities are fully automated through deep learning models without human intervention.', 'isMultiAnswer': False, 'domain_id': 3}, {'id': 'q094', 'question': 'Which AWS service can be used to automatically scale an application up and down without making capacity planning decisions?', 'options': {'A': 'AWS Auto Scaling', 'B': 'Amazon Redshift', 'C': 'AWS CloudTrail', 'D': 'AWS Lambda'}, 'answer': 'A', 'explanation': 'AWS Auto Scaling automatically adjusts the number of EC2 instances based on defined policies, eliminating the need for manual capacity planning decisions and ensuring the application always has the right amount of compute capacity.\nAmazon Redshift is a fully managed data warehouse service designed for running analytical queries across large datasets, and has no capability to automatically scale application infrastructure. AWS CloudTrail is a logging and auditing service that records API calls and account activity across an AWS environment, and does not manage or adjust application capacity. AWS Lambda is a serverless compute service that runs code in response to events without provisioning servers, but it is an event-driven execution environment rather than a service that scales existing application infrastructure up and down.', 'isMultiAnswer': False, 'domain_id': 3}, {'id': 'q095', 'question': 'Amazon Relational Database Service (Amazon RDS) offers which of the following benefits over traditional database management?', 'options': {'A': 'AWS manages the data stored in Amazon RDS tables', 'B': 'AWS manages the maintenance of the operating system', 'C': 'AWS automatically scales up instance types on demand', 'D': 'AWS manages the database type'}, 'answer': 'B', 'explanation': 'With Amazon RDS, AWS manages the underlying operating system patching, backups, and maintenance windows, freeing customers from OS-level administration while customers retain responsibility for their data, schema, and database-level configuration.\nAWS does not manage the data stored in RDS tables, as customers retain full responsibility for the data they load, modify, and delete within their databases. RDS does not automatically scale instance types on demand, as customers must manually resize instances or enable storage autoscaling, unlike serverless services such as DynamoDB which scale automatically. AWS does not manage the database type in RDS, as customers choose and remain responsible for selecting the database engine such as MySQL, PostgreSQL, or Oracle when creating an instance.', 'isMultiAnswer': False, 'domain_id': 3}, {'id': 'q098', 'question': 'Which service stores objects, provides real-time access to those objects, and offers versioning and lifecycle capabilities?', 'options': {'A': 'Amazon S3 Glacier', 'B': 'AWS Storage Gateway', 'C': 'Amazon S3', 'D': 'Amazon EBS'}, 'answer': 'C', 'explanation': 'Amazon S3 stores objects with real-time access, supports versioning to track and restore previous versions, and offers lifecycle policies to manage object transitions, making it the service that matches all three described capabilities.\nAmazon S3 Glacier is an archival storage service designed for data that is rarely accessed and can tolerate retrieval times of hours, and does not provide the real-time access or versioning capabilities the question describes. AWS Storage Gateway is a hybrid storage service that connects on-premises environments to AWS cloud storage for ongoing integration, and is not an object storage service with versioning or lifecycle management. Amazon EBS provides persistent block storage volumes that attach to EC2 instances, and does not store objects or support versioning and lifecycle policies.', 'isMultiAnswer': False, 'domain_id': 3}, {'id': 'q108', 'question': 'A company wants to expand from one AWS Region into a second AWS Region. What does the company need to do to start supporting the new Region?', 'options': {'A': 'Contact an AWS Account Manager to sign a new contract', 'B': 'Move an Availability Zone to the new Region', 'C': 'Begin deploying resources in the second Region', 'D': 'Download the AWS Management Console for the new Region'}, 'answer': 'C', 'explanation': 'AWS Regions are available globally and customers can begin provisioning resources in any Region at any time through the console, CLI, or API without any additional agreements or setup required.\nContacting an AWS Account Manager to sign a new contract is not required because AWS uses a self-service, pay-as-you-go model with no per-Region contracts. Availability Zones are fixed infrastructure components within a Region and cannot be moved or reassigned. The AWS Management Console is a web-based interface accessed through a browser and does not require a separate download for each Region.', 'isMultiAnswer': False, 'domain_id': 3}, {'id': 'q109', 'question': 'Why is it beneficial to use Elastic Load Balancers with applications?', 'options': {'A': 'They allow for the conversion from Application Load Balancers to Classic Load Balancers', 'B': 'They are capable of handling constant changes in network traffic patterns', 'C': 'They automatically adjust capacity', 'D': 'They are provided at no charge to users'}, 'answer': 'B', 'explanation': 'Elastic Load Balancers automatically distribute incoming traffic across multiple registered targets and adapt to constantly changing network traffic patterns without requiring manual intervention, ensuring no single target becomes a bottleneck.\nElastic Load Balancers do not convert between Application Load Balancers and Classic Load Balancers; these are distinct load balancer types that cannot be converted to one another, and migration requires deploying a new load balancer rather than in-place conversion. ELB does not itself adjust the number of compute instances; that is the responsibility of Auto Scaling groups working in conjunction with a load balancer. Elastic Load Balancing is not provided at no charge; there are per-hour charges for each load balancer plus data processing charges, making cost a factor when designing load-balanced architectures.', 'isMultiAnswer': False, 'domain_id': 3}, {'id': 'q116', 'question': 'Which AWS managed service is used to host databases?', 'options': {'A': 'AWS Batch', 'B': 'AWS Artifact', 'C': 'AWS Data Pipeline', 'D': 'Amazon RDS'}, 'answer': 'D', 'explanation': 'Amazon RDS is a fully managed relational database service that supports multiple database engines including MySQL, PostgreSQL, Oracle, and SQL Server, handling provisioning, patching, backups, and high availability automatically.\nAWS Batch is a fully managed service for running large-scale batch computing jobs across dynamically provisioned compute resources, and has no database hosting capability. AWS Artifact is a self-service portal that provides on-demand access to AWS compliance reports and security documentation, and is entirely unrelated to database hosting. AWS Data Pipeline (deprecated) is an orchestration service for scheduling and automating the movement and transformation of data between AWS services and on-premises sources, and is not a service for hosting or managing databases.', 'isMultiAnswer': False, 'domain_id': 3}, {'id': 'q119', 'question': 'Which AWS service provides a simple and scalable shared file storage solution for use with Linux-based AWS and on-premises servers?', 'options': {'A': 'Amazon S3', 'B': 'Amazon S3 Glacier', 'C': 'Amazon EBS', 'D': 'Amazon EFS'}, 'answer': 'D', 'explanation': 'Amazon Elastic File System (EFS) is a managed NFS file system that can be mounted simultaneously by multiple Linux EC2 instances and accessed from on-premises servers, providing simple, scalable shared file storage.\nAmazon S3 is an object storage service designed for storing and retrieving files via HTTP APIs, and does not provide a mountable shared file system for Linux servers. Amazon S3 Glacier is an archival storage class within Amazon S3 designed for long-term data retention with infrequent access, and has no shared file system capability. Amazon Elastic Block Store (EBS) provides block-level storage volumes that attach to a single EC2 instance at a time, and cannot be shared across multiple servers simultaneously.', 'isMultiAnswer': False, 'domain_id': 3}, {'id': 'q122', 'question': 'Which type of AWS storage is ephemeral and is deleted when an instance is stopped or terminated?', 'options': {'A': 'Amazon EBS', 'B': 'Amazon EC2 instance store', 'C': 'Amazon EFS', 'D': 'Amazon S3'}, 'answer': 'B', 'explanation': 'EC2 instance store provides ephemeral block storage that is physically attached to the host machine and is permanently deleted when the instance is stopped or terminated, making it suitable only for temporary data.\nAmazon EBS volumes are persistent block storage that exist independently of the instance lifecycle, so data is retained even after the instance is stopped or terminated. Amazon EFS is a persistent shared file system that remains available across multiple instances and is not tied to the lifecycle of any single instance. Amazon S3 is persistent object storage that exists independently of any compute instance and retains data until explicitly deleted.', 'isMultiAnswer': False, 'domain_id': 3}, {'id': 'q124', 'question': 'Which services are parts of the AWS serverless platform?', 'options': {'A': 'Amazon EC2, Amazon S3, Amazon Athena', 'B': 'Amazon Kinesis, Amazon SQS, Amazon EMR', 'C': 'AWS Step Functions, Amazon DynamoDB, Amazon SNS', 'D': 'Amazon Athena, Amazon Cognito, Amazon EC2'}, 'answer': 'C', 'explanation': 'AWS Step Functions, Amazon DynamoDB, and Amazon SNS are all fully serverless services that require no server provisioning and scale automatically, making this the only group composed entirely of serverless services.\nAmazon EC2 requires customers to provision and manage virtual server instances, and while Amazon S3 and Athena are serverless, EC2 disqualifies this group. Amazon EMR requires provisioning and managing clusters of servers for big data processing, disqualifying this group even though Kinesis and SQS are serverless. Amazon EC2 is not a serverless service, which disqualifies this group regardless of whether Athena and Cognito qualify individually.', 'isMultiAnswer': False, 'domain_id': 3}, {'id': 'q134', 'question': 'Which AWS service should be used for long-term, low-cost storage of data backups?', 'options': {'A': 'Amazon RDS', 'B': 'Amazon S3 Glacier', 'C': 'AWS Snowball', 'D': 'Amazon EBS'}, 'answer': 'B', 'explanation': 'Amazon S3 Glacier is designed for long-term archival and data backup at very low storage costs, making it the purpose-built service for retaining backups cheaply over extended periods.\nAmazon RDS is a fully managed relational database service for active transactional workloads, and is not designed for storing infrequently accessed backup archives at low cost. AWS Snowball is a physical data transport device used for migrating large volumes of data into or out of AWS, and is a migration tool rather than a long-term storage service. Amazon EBS provides persistent block storage volumes attached to EC2 instances for low-latency disk access, and is significantly more expensive per gigabyte than S3 Glacier for storing backup data that is accessed infrequently.', 'isMultiAnswer': False, 'domain_id': 3}, {'id': 'q149', 'question': "Which service's PRIMARY purpose is software version control?", 'options': {'A': 'AWS CodeBuild', 'B': 'AWS Command Line Interface (AWS CLI)', 'C': 'Amazon Cognito', 'D': 'AWS CodeCommit'}, 'answer': 'D', 'explanation': 'AWS CodeCommit is a fully managed Git-based source control service designed specifically for software version control, allowing teams to securely store and manage their code repositories.\nAWS CodeBuild is a fully managed build service that compiles source code and runs tests to produce deployment-ready packages, but its primary purpose is building and testing code rather than storing and versioning it. AWS CLI is a command-line tool for interacting with and managing AWS services and resources, and is not a source control or version management service. Amazon Cognito is a user identity and authentication service for web and mobile applications, and has no connection to software version control.', 'isMultiAnswer': False, 'domain_id': 3}, {'id': 'q151', 'question': 'Which of the following components of the AWS Global Infrastructure consists of one or more discrete data centers interconnected through low latency links?', 'options': {'A': 'Availability Zone', 'B': 'Edge location', 'C': 'Region', 'D': 'Private networking'}, 'answer': 'A', 'explanation': 'An Availability Zone consists of one or more discrete data centers with independent power and networking, interconnected to other AZs within the same Region via low-latency links.\nEdge locations are separate points of presence used for content delivery and caching, not data center clusters with redundant infrastructure. A Region is the broader geographic area that contains multiple Availability Zones, not the data center cluster itself. Private networking is not a component of the AWS global infrastructure hierarchy.', 'isMultiAnswer': False, 'domain_id': 3}, {'id': 'q154', 'question': 'A characteristic of edge locations is that they:', 'options': {'A': 'Host Amazon EC2 instances closer to users', 'B': 'Help lower latency and improve performance for users', 'C': 'Cache frequently changing data without reaching the origin server', 'D': 'Refresh data changes daily'}, 'answer': 'B', 'explanation': 'Edge locations cache content geographically close to end users, reducing round-trip distance and lowering latency to improve performance for global applications.\nHost Amazon EC2 instances closer to users. EC2 instances run in Regions and AZs, not at edge locations. Cache frequently changing data without reaching the origin server. Edge locations cache static or infrequently changing content, not frequently changing data. Refresh data changes daily. Edge locations serve cached content based on TTL settings, not on a fixed daily refresh cycle.', 'isMultiAnswer': False, 'domain_id': 3}, {'id': 'q164', 'question': 'Which service provides a hybrid storage service that enables on-premises applications to seamlessly use cloud storage?', 'options': {'A': 'Amazon S3 Glacier', 'B': 'AWS Snowball', 'C': 'AWS Storage Gateway', 'D': 'Amazon Elastic Block Storage (Amazon EBS)'}, 'answer': 'C', 'explanation': 'AWS Storage Gateway is a hybrid storage service that integrates on-premises environments with AWS cloud storage, presenting cloud storage as local file shares, volumes, or tape to on-premises applications.\nAmazon S3 Glacier is an archival storage class within Amazon S3 designed for long-term data retention with infrequent access, and does not provide a hybrid storage integration layer for on-premises applications. AWS Snowball is a physical data transfer device used to move large volumes of data into or out of AWS, and is a migration tool rather than an ongoing hybrid storage service. Amazon Elastic Block Store (EBS) provides block-level storage volumes that attach to EC2 instances within AWS, and cannot be accessed directly by on-premises applications as a seamless cloud storage extension.', 'isMultiAnswer': False, 'domain_id': 3}, {'id': 'q166', 'question': 'Which of the following is a component of the AWS Global Infrastructure?', 'options': {'A': 'Amazon Alexa', 'B': 'AWS Regions', 'C': 'Amazon Lightsail', 'D': 'AWS Organizations'}, 'answer': 'B', 'explanation': 'AWS Regions are the physical, geographically distributed components of the AWS Global Infrastructure, each containing multiple Availability Zones that provide redundancy and fault isolation.\nAmazon Alexa is a voice assistant service that enables conversational interactions with applications, and is not a component of the physical infrastructure that underpins AWS. Amazon Lightsail is a simplified compute service designed for developers who need an easy way to launch virtual servers and applications, and is not an infrastructure component. AWS Organizations is an account management service that enables centralized governance and billing across multiple AWS accounts, and is not part of the AWS Global Infrastructure.', 'isMultiAnswer': False, 'domain_id': 3}, {'id': 'q172', 'question': 'Which of the following AWS features enables a user to launch a pre-configured Amazon Elastic Compute Cloud (Amazon EC2) instance?', 'options': {'A': 'Amazon Elastic Block Store (Amazon EBS)', 'B': 'Amazon Machine Image', 'C': 'Amazon EC2 Systems Manager', 'D': 'Amazon AppStream 2.0'}, 'answer': 'B', 'explanation': 'An Amazon Machine Image is a pre-configured template containing the operating system, application server, and application code used to launch a new EC2 instance in a consistent, known state.\nAmazon EBS is a block storage service that provides persistent volumes to attach to EC2 instances, not a template for launching pre-configured instances. AWS Systems Manager provides operational tools for managing, patching, and automating tasks on running EC2 instances, but does not launch pre-configured instances. Amazon AppStream 2.0 is an application streaming service that delivers desktop applications to users through a browser, entirely unrelated to EC2 instance configuration.', 'isMultiAnswer': False, 'domain_id': 3}, {'id': 'q066', 'question': 'Which benefits are included with the AWS Business Support plan?', 'options': {'A': '24/7 assistance by way of live chat or a telephone call', 'B': 'Support from a dedicated AWS Technical Account Manager', 'C': 'An unlimited number of cases and contacts', 'D': '15-minute response time for production system interruption cases', 'E': 'Annual operational reviews with AWS Solutions Architects'}, 'answer': ['A', 'C'], 'explanation': 'AWS Business Support includes 24/7 access to Cloud Support Engineers via phone, email, and chat, plus an unlimited number of support cases and contacts.\nSupport from a dedicated Technical Account Manager who provides proactive guidance and acts as a primary contact is exclusively available with the AWS Enterprise Support plan and is not included in Business Support. A 15-minute response time for production system interruption cases is an Enterprise Support feature. Business Support provides a one-hour response SLA for production system-down cases, not 15 minutes. Annual operational reviews with AWS Solutions Architects are an Enterprise Support benefit and are not included in the Business Support plan.', 'isMultiAnswer': True, 'domain_id': 4}, {'id': 'q034', 'question': 'As part of the Enterprise support plan, who is the primary point of contact for ongoing support needs?', 'options': {'A': 'AWS Identity and Access Management (IAM) user', 'B': 'Infrastructure Event Management (IEM) engineer', 'C': 'AWS Consulting Partners', 'D': 'AWS Technical Account Manager (TAM)'}, 'answer': 'D', 'explanation': 'The AWS Technical Account Manager is included in the Enterprise Support plan as the primary dedicated contact who provides proactive guidance and coordinates AWS support across your account.\nAn AWS IAM user is an identity within an AWS account used to authenticate and authorise access to AWS services, and is not a support contact or a role within the AWS Support organization. An Infrastructure Event Management engineer provides architectural guidance and real-time support during specific planned events under the Enterprise Support plan, but is engaged for specific events rather than serving as the ongoing primary support contact. AWS Consulting Partners are professional services firms in the AWS Partner Network that help customers design and build on AWS, and are external organizations rather than AWS Support personnel assigned to an account.', 'isMultiAnswer': False, 'domain_id': 4}, {'id': 'q035', 'question': 'How can you view the distribution of AWS spending in one of your AWS accounts?', 'options': {'A': 'By using Amazon VPC console', 'B': 'By contacting the AWS Support team', 'C': 'By using AWS Cost Explorer', 'D': 'By contacting the AWS Finance team'}, 'answer': 'C', 'explanation': 'AWS Cost Explorer provides interactive charts and reports that visualise your AWS spending patterns over time, broken down by service, account, or tag.\nThe Amazon VPC console is a networking tool for managing virtual private clouds, subnets, gateways, and network configuration, and has no connection to billing information or spending distribution. Contacting the AWS Support team provides technical guidance and issue resolution, and is not a self-service mechanism for viewing the distribution of AWS spending across your account. Contacting the AWS Finance team is not a supported customer-facing channel for accessing billing and spending information, which is available directly through the AWS Management Console via Cost Explorer and billing dashboards.', 'isMultiAnswer': False, 'domain_id': 4}, {'id': 'q049', 'question': 'What does AWS provide to deploy popular technologies such as IBM MQ on AWS with the least amount of effort and time?', 'options': {'A': 'Amazon Aurora', 'B': 'Amazon CloudWatch', 'C': 'AWS Quick Start reference deployments', 'D': 'AWS OpsWorks'}, 'answer': 'C', 'explanation': 'AWS Quick Start reference deployments provide automated gold-standard templates that deploy popular IT solutions on AWS in minutes, giving administrators a fast path to production-ready environments built on AWS best practices.\nAmazon Aurora is a fully managed relational database compatible with MySQL and PostgreSQL, and is a database service with no capability to deploy or provision third-party technologies or solutions. Amazon CloudWatch collects metrics, logs, and event data from AWS services and resources to provide operational monitoring and alerting, and is a monitoring service with no deployment or provisioning capability. AWS OpsWorks (deprecated) was a configuration management service that used Chef and Puppet to automate server configuration, and while it could automate some infrastructure tasks it is not a pre-built deployment resource for rapidly deploying popular third-party technologies with minimal effort. Note: AWS OpsWorks was deprecated in 2024.', 'isMultiAnswer': False, 'domain_id': 4}, {'id': 'q052', 'question': 'Which of the following Reserved Instance (RI) pricing models provides the highest average savings compared to On-Demand pricing?', 'options': {'A': 'One-year, No Upfront, Standard RI pricing', 'B': 'One-year, All Upfront, Convertible RI pricing', 'C': 'Three-year, All Upfront, Standard RI pricing', 'D': 'Three-year, No Upfront, Convertible RI pricing'}, 'answer': 'C', 'explanation': 'Three-year All Upfront Standard RIs combine the longest commitment term with full prepayment and the Standard type, which together yield the deepest discount compared to On-Demand pricing.\nA one-year No Upfront Standard RI offers the lowest upfront cost but provides the smallest discount among the options listed, as the short term and absence of prepayment both reduce the overall savings. A one-year All Upfront Convertible RI benefits from full prepayment but is limited by the shorter term and the Convertible type, which offers less discount than Standard RIs in exchange for flexibility to exchange attributes. A three-year No Upfront Convertible RI benefits from the long commitment term but sacrifices discount depth through both the absence of prepayment and the Convertible type designation, making it less cost-effective than the All Upfront Standard equivalent.', 'isMultiAnswer': False, 'domain_id': 4}, {'id': 'q061', 'question': 'A customer is using multiple AWS accounts with separate billing. How can the customer take advantage of volume discounts with minimal impact to the AWS resources?', 'options': {'A': 'Create one global AWS account and move all AWS resources to that account', 'B': 'Sign up for three years of Reserved Instance pricing up front', 'C': 'Use the consolidated billing feature from AWS Organizations', 'D': 'Sign up for the AWS Enterprise support plan to get volume discounts'}, 'answer': 'C', 'explanation': 'AWS Organizations consolidated billing aggregates usage across all member accounts, qualifying the organization for volume pricing tiers without requiring resource consolidation or upfront RI commitments.\nCreating one global account and moving all resources is a high-impact change that would eliminate account-level isolation, security boundaries, and governance, and it is unnecessary because consolidated billing earns the same volume discounts without migration. Reserved Instance pricing locks compute into a specific instance type and term, which lowers cost for predictable workloads but does not provide cross-account volume discounts. The Enterprise Support plan adds Technical Account Managers and premium support, but support tiers do not grant volume discounts on service usage.', 'isMultiAnswer': False, 'domain_id': 4}, {'id': 'q062', 'question': 'Which Amazon EC2 pricing model offers the MOST significant discount when compared to On-Demand instances?', 'options': {'A': 'Partial Upfront Reserved Instances for a 1-year term', 'B': 'All Upfront Reserved Instances for a 1-year term', 'C': 'All Upfront Reserved Instances for a 3-year term', 'D': 'No Upfront Reserved Instances for a 3-year term'}, 'answer': 'C', 'explanation': 'All Upfront Reserved Instances for a 3-year term provide the maximum possible EC2 discount because you combine the longest commitment term with full prepayment, which together yield the deepest savings compared to On-Demand pricing.\nPartial Upfront Reserved Instances for a 1-year term offer a moderate discount, but the shorter term and partial prepayment both reduce the total savings compared to the 3-year All Upfront option. All Upfront Reserved Instances for a 1-year term offer a good discount through full prepayment but are limited by the shorter commitment term, which yields less total savings than a 3-year commitment. No Upfront Reserved Instances for a 3-year term benefit from the long commitment term but forgo the additional discount that comes with upfront payment, making them less cost-effective than All Upfront options.', 'isMultiAnswer': False, 'domain_id': 4}, {'id': 'q068', 'question': 'A user must meet compliance and software licensing requirements that state a workload must be hosted on a physical server. Which Amazon EC2 instance pricing option will meet these requirements?', 'options': {'A': 'Dedicated Hosts', 'B': 'Dedicated Instances', 'C': 'Spot Instances', 'D': 'Reserved Instances'}, 'answer': 'A', 'explanation': 'EC2 Dedicated Hosts provide a physical server dedicated entirely to your use with full visibility into sockets, cores, and host ID, which is required for server-bound software licensing such as BYOL and for certain compliance frameworks that mandate physical isolation.\nDedicated Instances run on hardware dedicated to a single customer but do not provide visibility into the specific physical host, which is required for most per-socket or per-core licensing models and does not satisfy all compliance requirements for physical server isolation. Spot Instances use spare AWS capacity at a significant discount but can be interrupted by AWS at any time, making them unsuitable for workloads with compliance requirements that mandate consistent physical server hosting. Reserved Instances are a pricing commitment for EC2 capacity that can reduce costs over a 1 or 3-year term, but they run on shared infrastructure and do not provide physical server isolation or host-level visibility required for BYOL licensing.', 'isMultiAnswer': False, 'domain_id': 4}]}


def annotate_mit_question(q, seq_idx):
    dom_id = q["domain_id"]
    opts_dict = q["options"]
    opt_keys = sorted(opts_dict.keys())
    choices = [opts_dict[k].strip() for k in opt_keys]

    ans_raw = q["answer"]
    ans_keys = ans_raw if isinstance(ans_raw, list) else [ans_raw]
    answer_indices = [opt_keys.index(k) for k in ans_keys]
    answer_index = answer_indices[0]

    ans_texts = [choices[idx] for idx in answer_indices]
    ans_labels = [f"{opt_keys[idx]}) {choices[idx]}" for idx in answer_indices]
    answer_text = " / ".join(ans_labels)

    ans_lower = " ".join(ans_texts).lower()
    combined = (q["question"] + " " + " ".join(ans_texts)).lower()

    matched = []
    for pat, svc_ko, desc_ko in CONCEPT_RULES:
        if re.search(pat, ans_lower):
            matched.append((svc_ko, desc_ko))
    if not matched:
        for pat, svc_ko, desc_ko in CONCEPT_RULES:
            if re.search(pat, combined):
                matched.append((svc_ko, desc_ko))
    if not matched:
        matched.append((DOM_SHORT[dom_id], "AWS CLF-C02 공식 출제 기준의 핵심 클라우드 원리 및 서비스 활용 문항"))

    primary_svc, primary_desc = matched[0]
    kws = []
    seen = set()
    for m_svc, _ in matched[:3]:
        if m_svc not in seen:
            seen.add(m_svc)
            kws.append(m_svc)
    if DOM_SHORT[dom_id] not in seen:
        kws.append(DOM_SHORT[dom_id])

    ans_summary = " / ".join(ans_texts)
    if len(ans_summary) > 110:
        ans_summary = ans_summary[:107] + "..."

    title = f"[{DOM_SHORT[dom_id]}] {primary_svc} (#{q['id']})"
    explanation = (
        f"[핵심 포인트] {primary_desc}. 정답 핵심: {ans_summary}\n\n"
        f"[원문 해설] {q['explanation'].strip()}"
    )

    is_multi = len(answer_indices) > 1
    qtype_id = 2 if is_multi else 1
    qtype_name = "복수 선택 (2개)" if is_multi else "단일 선택"

    return {
        "round_id": q["round_id"],
        "question_no": seq_idx,
        "domain_id": dom_id,
        "qtype_id": qtype_id,
        "qtype": qtype_name,
        "source": "CloudCertPrep (MIT)",
        "source_qid": q["id"],
        "title": title,
        "question_text": q["question"].strip(),
        "choices": choices,
        "answer_index": answer_index,
        "answer_indices": answer_indices,
        "answer_text": answer_text,
        "core_keywords": ", ".join(kws),
        "explanation": explanation,
    }


def build_all_questions():
    rows = []

    # Round 1: Official AWS Sample Questions PDF (10 questions)
    for idx, pq in enumerate(PDF_QUESTIONS, start=1):
        ans_indices = pq["answer_indices"]
        labels = ["A", "B", "C", "D", "E"]
        ans_text = " / ".join(f"{labels[i]}) {pq['choices'][i]}" for i in ans_indices)
        explanation = f"{pq['ko_point']}\n\n[원문 해설] {pq['orig_explanation']}"
        rows.append({
            "round_id": 1,
            "question_no": idx,
            "domain_id": pq["domain_id"],
            "qtype_id": 1,
            "qtype": "단일 선택",
            "source": "AWS Official Sample Questions PDF",
            "source_qid": pq["source_qid"],
            "title": pq["title"],
            "question_text": pq["question_text"],
            "choices": pq["choices"],
            "answer_index": ans_indices[0],
            "answer_indices": ans_indices,
            "answer_text": ans_text,
            "core_keywords": pq["core_keywords"],
            "explanation": explanation,
        })

    # Round 2: Set A (65 questions)
    set_a_sorted = sorted(MIT_DATA["set_a"], key=lambda x: (x["domain_id"], x["id"]))
    for idx, q in enumerate(set_a_sorted, start=1):
        q_copy = dict(q)
        q_copy["round_id"] = 2
        rows.append(annotate_mit_question(q_copy, idx))

    # Round 3: Set B (65 questions)
    set_b_sorted = sorted(MIT_DATA["set_b"], key=lambda x: (x["domain_id"], x["id"]))
    for idx, q in enumerate(set_b_sorted, start=1):
        q_copy = dict(q)
        q_copy["round_id"] = 3
        rows.append(annotate_mit_question(q_copy, idx))

    return rows


def build_database():
    if os.path.exists(DB_PATH):
        os.remove(DB_PATH)

    all_questions = build_all_questions()

    conn = sqlite3.connect(DB_PATH)
    cur = conn.cursor()

    cur.executescript("""
    PRAGMA foreign_keys = ON;

    CREATE TABLE exam_rounds (
        round_id INTEGER PRIMARY KEY,
        round_title TEXT NOT NULL,
        exam_year INTEGER NOT NULL,
        exam_date TEXT NOT NULL,
        agency TEXT NOT NULL,
        source_type TEXT NOT NULL,
        key_trend TEXT NOT NULL
    );

    CREATE TABLE categories_domain (
        domain_id INTEGER PRIMARY KEY,
        domain_code TEXT NOT NULL UNIQUE,
        domain_name TEXT NOT NULL,
        official_weight_pct REAL NOT NULL,
        description TEXT NOT NULL
    );

    CREATE TABLE categories_qtype (
        qtype_id INTEGER PRIMARY KEY,
        qtype_code TEXT NOT NULL UNIQUE,
        qtype_name TEXT NOT NULL,
        select_count INTEGER NOT NULL,
        description TEXT NOT NULL
    );

    CREATE TABLE questions (
        question_id INTEGER PRIMARY KEY AUTOINCREMENT,
        round_id INTEGER NOT NULL REFERENCES exam_rounds(round_id),
        question_no INTEGER NOT NULL,
        domain_id INTEGER NOT NULL REFERENCES categories_domain(domain_id),
        qtype_id INTEGER NOT NULL REFERENCES categories_qtype(qtype_id),
        qtype TEXT NOT NULL,
        source TEXT NOT NULL,
        source_qid TEXT NOT NULL,
        title TEXT NOT NULL,
        question_text TEXT NOT NULL,
        choices_json TEXT NOT NULL,
        answer_index INTEGER NOT NULL,
        answer_indices_json TEXT NOT NULL,
        answer_text TEXT NOT NULL,
        core_keywords TEXT NOT NULL,
        explanation TEXT NOT NULL
    );

    CREATE TABLE domain_analytics (
        domain_id INTEGER PRIMARY KEY REFERENCES categories_domain(domain_id),
        domain_name TEXT NOT NULL,
        official_weight_pct REAL NOT NULL,
        total_questions INTEGER NOT NULL,
        share_pct REAL NOT NULL,
        single_count INTEGER NOT NULL,
        multi_count INTEGER NOT NULL,
        pdf_count INTEGER NOT NULL,
        mit_count INTEGER NOT NULL
    );

    CREATE VIEW v_mode_exam AS
    SELECT q.question_id, q.round_id, r.round_title, r.exam_year, r.agency,
           q.question_no, q.domain_id, d.domain_name, q.qtype_id, q.qtype,
           q.source, q.source_qid, q.title, q.question_text, q.choices_json
    FROM questions q
    JOIN exam_rounds r ON q.round_id = r.round_id
    JOIN categories_domain d ON q.domain_id = d.domain_id;

    CREATE VIEW v_mode_explanation AS
    SELECT q.question_id, q.round_id, r.round_title, r.exam_year, r.agency,
           q.question_no, q.domain_id, d.domain_name, q.qtype_id, q.qtype,
           q.source, q.source_qid, q.title, q.question_text, q.choices_json,
           q.answer_index, q.answer_indices_json, q.answer_text,
           q.core_keywords, q.explanation
    FROM questions q
    JOIN exam_rounds r ON q.round_id = r.round_id
    JOIN categories_domain d ON q.domain_id = d.domain_id;
    """)

    cur.executemany("INSERT INTO exam_rounds VALUES (?, ?, ?, ?, ?, ?, ?)", EXAM_ROUNDS)
    cur.executemany("INSERT INTO categories_domain VALUES (?, ?, ?, ?, ?)", CATEGORIES_DOMAIN)
    cur.executemany("INSERT INTO categories_qtype VALUES (?, ?, ?, ?, ?)", CATEGORIES_QTYPE)

    q_tuples = [
        (
            q["round_id"],
            q["question_no"],
            q["domain_id"],
            q["qtype_id"],
            q["qtype"],
            q["source"],
            q["source_qid"],
            q["title"],
            q["question_text"],
            json.dumps(q["choices"], ensure_ascii=False),
            q["answer_index"],
            json.dumps(q["answer_indices"]),
            q["answer_text"],
            q["core_keywords"],
            q["explanation"],
        )
        for q in all_questions
    ]

    cur.executemany("""
        INSERT INTO questions (
            round_id, question_no, domain_id, qtype_id, qtype,
            source, source_qid, title, question_text, choices_json,
            answer_index, answer_indices_json, answer_text, core_keywords, explanation
        ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
    """, q_tuples)

    total_q = len(all_questions)
    analytics_rows = []
    for dom_id, _code, dom_name, weight_pct, _desc in CATEGORIES_DOMAIN:
        dom_qs = [q for q in all_questions if q["domain_id"] == dom_id]
        cnt = len(dom_qs)
        share = round((cnt / total_q) * 100, 1) if total_q else 0.0
        single_c = sum(1 for q in dom_qs if q["qtype_id"] == 1)
        multi_c = sum(1 for q in dom_qs if q["qtype_id"] == 2)
        pdf_c = sum(1 for q in dom_qs if q["source"] == "AWS Official Sample Questions PDF")
        mit_c = sum(1 for q in dom_qs if q["source"] == "CloudCertPrep (MIT)")
        analytics_rows.append((dom_id, dom_name, weight_pct, cnt, share, single_c, multi_c, pdf_c, mit_c))

    cur.executemany("INSERT INTO domain_analytics VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)", analytics_rows)
    conn.commit()

    with open(SQL_DUMP_PATH, "w", encoding="utf-8") as f:
        for line in conn.iterdump():
            f.write(f"{line}\n")

    export_data = {
        "meta": {
            "cert_id": "aws-clf-c02",
            "exam_code": "CLF-C02",
            "level": "Foundational",
            "cert_group": "AWS 클라우드 자격",
            "exam_stage": "필기",
            "title": "AWS Certified Cloud Practitioner (CLF-C02) 공식 샘플 · 실전 모의고사 RDB",
            "rounds_count": len(EXAM_ROUNDS),
            "questions_count": len(all_questions),
            "rounds_range": "공식 샘플 10문항 + 실전 모의고사 A/B세트 각 65문항 (총 140문항)",
            "updated_at": "2026-11-26",
        },
        "rounds": [
            {
                "round_id": r[0],
                "round_title": r[1],
                "exam_year": r[2],
                "exam_date": r[3],
                "agency": r[4],
                "source_type": r[5],
                "key_trend": r[6],
            }
            for r in EXAM_ROUNDS
        ],
        "domains": [
            {
                "domain_id": d[0],
                "domain_code": d[1],
                "domain_name": d[2],
                "official_weight_pct": d[3],
                "description": d[4],
            }
            for d in CATEGORIES_DOMAIN
        ],
        "qtypes": [
            {
                "qtype_id": t[0],
                "qtype_code": t[1],
                "qtype_name": t[2],
                "select_count": t[3],
                "description": t[4],
            }
            for t in CATEGORIES_QTYPE
        ],
        "analytics": [
            {
                "domain_id": a[0],
                "domain_name": a[1],
                "official_weight_pct": a[2],
                "total_questions": a[3],
                "share_pct": a[4],
                "single_count": a[5],
                "multi_count": a[6],
                "pdf_count": a[7],
                "mit_count": a[8],
            }
            for a in analytics_rows
        ],
        "questions": [],
    }

    for row in cur.execute("""
        SELECT question_id, round_id, round_title, exam_year, agency,
               question_no, domain_id, domain_name, qtype_id, qtype,
               source, source_qid, title, question_text, choices_json,
               answer_index, answer_indices_json, answer_text,
               core_keywords, explanation
        FROM v_mode_explanation
        ORDER BY round_id ASC, question_no ASC
    """):
        export_data["questions"].append({
            "question_id": row[0],
            "round_id": row[1],
            "round_title": row[2],
            "exam_year": row[3],
            "agency": row[4],
            "question_no": row[5],
            "domain_id": row[6],
            "domain_name": row[7],
            "qtype_id": row[8],
            "qtype": row[9],
            "source": row[10],
            "source_qid": row[11],
            "title": row[12],
            "question_text": row[13],
            "choices": json.loads(row[14]),
            "answer_index": row[15],
            "answer_indices": json.loads(row[16]),
            "answer_text": row[17],
            "core_keywords": row[18],
            "explanation": row[19],
        })

    with open(JSON_EXPORT_PATH, "w", encoding="utf-8") as f:
        json.dump(export_data, f, ensure_ascii=False, indent=2)

    integrity = cur.execute("PRAGMA integrity_check").fetchone()[0]
    conn.close()
    print(f"[OK] Built AWS CLF-C02 RDB: {len(EXAM_ROUNDS)} rounds, {len(all_questions)} questions, integrity={integrity}")
    print(f"     DB:   {DB_PATH}")
    print(f"     SQL:  {SQL_DUMP_PATH}")
    print(f"     JSON: {JSON_EXPORT_PATH}")


if __name__ == "__main__":
    build_database()
